/* The seven Geo tabs. Each only draws from the shared state (G.v); none of them calls Google except on an explicit button. */
(function () {
'use strict';
const { $, $$, esc, I, S, num } = PI;
const T = PI.geoTabs = {};
const empty = (el, G, what) => { const rd = PI.geoBrief.ready(G); el.innerHTML = `<div class="gx-empty">${I('map-pin')}<b>${rd.ok ? 'Ready when you are' : 'One more thing first'}</b><span>${esc(rd.ok ? what : rd.summary)}</span>${rd.ok ? `<button class="btn pri sm" id="gemgo">${esc(rd.mode.actionLabel)}</button>` : ''}</div>`; const b = $('#gemgo'); if (b) b.onclick = () => $('#gprimary').click(); };
const ev = (res, ids) => ids && ids.length ? ' · ' + esc(ids.join(', ')) : '';
const src = d => d.error ? `<p class="gx-fine">${esc(d.error)}</p>` : `<p class="gx-fine">${esc(d.title)} · ${d.year ? 'year ' + esc(d.year) + ' · ' : ''}by ${esc(d.level)} · <a href="${esc(d.url)}" target="_blank" rel="noopener">Qatar Open Data</a>${d.modified ? ' · updated ' + esc(d.modified.slice(0, 10)) : ''}</p>`;
const short = s => s.length > 30 ? s.slice(0, 28) + '…' : s;
const opx = (G, r) => { const cl = G.clients(), se = G.v.result && G.v.result.season; return { clientNearestM: cl.length ? G.C.nearestM(r.site, cl) : null, seasonAdj: se ? se.adjustment : 0 }; };
const pct = x => (x >= 0 ? '+' : '') + Math.round(x * 100) + '%';
const legend = (G, res) => res.recipe.factors.map(f => `<span><i style="background:${G.M.color(res, f.cat)}"></i>${esc(G.meta.categories[f.cat])}</span>`).join('');

/* ===== 0. Plan: locations + inventory + audience -> the winning set of screens and branches ===== */
T.plan = (el, G) => {
  const { v, M, C } = G, P = v.plan;
  if (!P) { el.innerHTML = `<div class="gx-empty">${I('sparkles')}<b>Build a plan in three steps</b><span>1. Type a brand or branch network and press Find. 2. Keep the full OOH inventory (or filter it). 3. Choose the audience. Then press Build plan: the tool finds the audience areas around every location, tests five ways of choosing screens, and recommends the winner with the reasons.</span></div>`; return; }
  const W = P.winner, pc = x => x == null ? '<span class="gx-fine">n/a</span>' : Math.round(x * 100), mk = Object.keys(P.metrics), areaOf = id => P.areas.find(a => a.id === id) || {}, band = s => s == null ? 'mut' : s >= 70 ? 'ok' : s >= 40 ? 'warn' : 'bad';
  const pill = st => `<span class="gx-pill ${st === 'Validated' ? 'ok' : 'warn'}">${st}</span>`, scored = P.areas.filter(a => a.score != null).length, top = P.branches.filter(b => b.value != null).slice(0, 10);
  const people = [...new Set(W.assets.map(x => x.area))].reduce((n, id) => n + (areaOf(id).population || 0), 0);
  el.innerHTML = `<div class="gx-hero"><div><small>Recommended plan · ${esc(P.q)} · ${esc(P.recipe.label)} · ${esc(P.inv)}</small><h3>${esc(W.name)} <span class="gx-pill ok">${W.total ?? 'n/a'} / 100</span></h3>
        <ul class="gx-why">${W.why.map(x => `<li>${esc(x)}</li>`).join('') || '<li>There was not enough evidence to separate the plans.</li>'}</ul></div>
      <div class="gx-tiles"><div><b>${W.assets.length}</b><small>OOH assets chosen</small></div><div><b>${new Set(W.assets.map(x => x.branch)).size} of ${P.branches.length}</b><small>Branches supported</small></div><div><b>${people ? 'about ' + num(people) : 'Unknown'}</b><small>People in the chosen areas (estimate)</small></div><div><b>${W.assets.filter(x => x.status === 'Validated').length} of ${W.assets.length}</b><small>Passed every check</small></div></div>
      <div class="gx-acts"><button class="btn pri sm" id="gpsave">${I('save')}Save</button><button class="btn sm" id="gpdeep">${I('target')}Analyse the chosen assets in detail</button><button class="btn sm" id="gpcsv">${I('download')}Download the plan (CSV)</button></div></div>
    <div class="gx-cov" role="note">${P.eligibleAssets ? `<b>${num(P.eligibleAssets)}</b> assets in the inventory → ` : ''}<b>${num(P.candidates)}</b> inside the audience areas around the ${P.branches.length} locations → <b>${num(P.candidates - (P.rejected || 0))}</b> passed the checks → <b>${W.assets.length}</b> chosen. ${P.planning.researched != null ? `${P.planning.researched} of ${P.planning.areas} areas hold OOH assets and were researched; the others were not scored.` : ''}</div>
    <div class="gx-card" style="margin-bottom:14px"><h4>Action matrix</h4><div class="gx-acts3">${[['DO NOW', 'ok', W.assets.filter(x => x.status === 'Validated'), 'Passed every check. Confirm availability, facing and price with the supplier.'], ['TEST', 'warn', W.assets.filter(x => x.status !== 'Validated'), 'Chosen, but a check was flagged. Open the checks and validate before booking.']].map(([k, c, list, txt]) => `<div><h5><span class="gx-pill ${c}">${k}</span> ${list.length} assets</h5><p class="gx-fine">${txt}</p><p class="gx-fine">${list.slice(0, 12).map(x => esc(x.id)).join(', ')}${list.length > 12 ? ' and ' + (list.length - 12) + ' more' : ''}</p></div>`).join('')}<div><h5><span class="gx-pill mut">WATCH</span> ${P.areas.filter(x => x.score == null).length} areas</h5><p class="gx-fine">Location areas with no OOH asset nearby or no evidence. They were not scored, so nothing is claimed about them.</p></div></div></div>
    <div class="gx-top"><div class="gx-map card"><div class="gx-mapbox" id="gmapbox"></div><div class="gx-ctl"><button class="btn xs" id="gpfit">${I('target')}Fit plan</button><button class="btn xs" id="gqatar">Qatar</button></div>
        <div class="gx-layers"><b>On the map</b><label><i style="background:#2F6BFF"></i> Chosen OOH assets</label><label><i style="background:#12121A"></i> ${esc(P.q)} locations</label><label><i style="background:#1FA971"></i> Strong ${esc(P.recipe.label.toLowerCase())} area</label><label><i style="background:#D99A12"></i> Moderate area</label><label><i style="background:#E5486F"></i> Weak area</label><label><i style="background:#98A2B3"></i> Other assets</label></div></div>
      <div class="gx-card"><h4>Chosen OOH assets <small>${W.assets.length} of ${P.candidates} inside audience areas${P.rejected ? ' · ' + P.rejected + ' rejected by the checks' : ''}</small></h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>#</th><th>Asset</th><th>Near</th><th>Area fit</th><th>Checks</th></tr></thead><tbody>${W.assets.map((x, i) => `<tr data-pa="${esc(x.id)}"><td>${i + 1}</td><td dir="auto"><b>${esc(short(x.name || x.id))}</b><small>${[x.vendor, x.format, x.faces > 1 ? x.faces + ' faces here' : ''].filter(Boolean).map(esc).join(' · ')}</small></td><td dir="auto">${esc(short(x.branchName || 'Branch'))}<small>${C.km(x.distanceM)}</small></td><td><span class="gx-pill ${band(areaOf(x.area).score)}">${areaOf(x.area).score ?? 'n/a'}</span></td><td><details><summary>${pill(x.status)}</summary><ul class="gx-chk">${x.checks.map(c => `<li class="${c.ok ? 'ok' : 'no'}">${esc(c.label)}</li>`).join('')}</ul></details></td></tr>`).join('') || '<tr><td colspan="5">No asset passed the checks.</td></tr>'}</tbody></table></div></div></div>
    <div class="gx-card" style="margin-bottom:14px"><h4>How the plans compared <small>${esc(P.objective === 'general' ? 'general awareness' : P.objective)} priorities</small></h4><div class="gx-tw"><table class="gx-t gx-cmp"><thead><tr><th>Plan</th><th>Score</th>${mk.map(k => `<th title="${esc(P.metrics[k])}">${esc(P.metrics[k])}</th>`).join('')}<th title="How many of the five priority settings this plan wins under">Wins</th></tr></thead><tbody>${P.strategies.map(s => `<tr class="${s.id === W.id ? 'on' : ''}"><td><b>${esc(s.name)}</b><small>${esc(s.idea)}</small></td><td><b>${s.total ?? 'n/a'}</b></td>${mk.map(k => `<td>${pc(s.scorecard[k])}</td>`).join('')}<td>${s.wins} of 5</td></tr>`).join('')}</tbody></table></div>
        <p class="gx-fine">Every plan is scored on the same evidence, 0 to 100 per line. "Wins" re-runs the comparison with the priorities of each objective, to show whether the winner depends on how you weigh things.</p></div>
    <div class="gx-card" style="margin-bottom:14px"><h4>Best branches for ${esc(P.recipe.label.toLowerCase())} <small>top ${top.length} of ${P.branches.length}</small></h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>#</th><th>Branch</th><th>Area fit</th><th>People nearby (est.)</th><th>Chosen screens within 500 m</th><th>Value</th></tr></thead><tbody>${top.map((b, i) => `<tr><td>${i + 1}</td><td dir="auto"><b>${esc(short(b.branch.name || b.branch.id))}</b><small>${esc([b.area.zone, b.area.municipality].filter(Boolean).join(' · '))}</small></td><td><span class="gx-pill ${band(b.area.score)}">${b.area.score ?? 'n/a'}</span></td><td>${b.area.population ? num(b.area.population) : '<span class="gx-fine">Unknown</span>'}</td><td>${b.support}</td><td><b>${b.value}</b></td></tr>`).join('') || '<tr><td colspan="6">No branch area could be scored.</td></tr>'}</tbody></table></div>
        <p class="gx-fine">Value blends the area's audience fit (50%), the people estimated around it (30%) and the chosen screens that support it (20%).</p></div>
    <div class="gx-row2"><details class="gx-card"><summary><b>Audience areas</b> · ${scored} of ${P.areas.length} scored · ${P.areasWithAssets} contain OOH assets</summary><div class="gx-tw"><table class="gx-t"><thead><tr><th>Area</th><th>Branches</th><th>Fit</th><th>What is there</th><th>People (est.)</th><th>Radius</th></tr></thead><tbody>${P.areas.slice().sort((a, b) => (b.score ?? -1) - (a.score ?? -1)).map(a => `<tr><td>${esc([a.zone, a.municipality].filter(Boolean).join(' · ') || a.id)}</td><td>${a.branches.length}</td><td><span class="gx-pill ${band(a.score)}">${a.score ?? 'n/a'}</span></td><td><small>${a.hasAssets === false ? 'No OOH asset nearby, not researched' : (a.factors || []).filter(f => f.count != null).map(f => f.count + ' ' + esc(f.label.toLowerCase())).join(', ') || 'No place evidence'}</small></td><td>${a.population ? num(a.population) : '–'}<small>${esc(a.popBasis || '')}</small></td><td>${C.km(a.radius)}</td></tr>`).join('')}</tbody></table></div></details>
      <div class="gx-card"><h4>Limits and method</h4><ul class="gx-list">${P.limits.map(x => `<li>${esc(x)}</li>`).join('')}</ul><p class="gx-fine">This run: ${P.planning.requested - P.planning.cached} new Google lookups, ${P.planning.cached} reused. ${P.season && P.season.peak ? 'Strongest window ahead for this audience: ' + esc(P.season.peak.name) + (P.season.peak.inDays ? ' in ' + P.season.peak.inDays + ' days.' : ' now.') : ''}</p></div></div>`;
  const chosen = new Set(W.assets.map(x => x.id)), rest = G.filtered().filter(r => !chosen.has(r.id)).slice(0, 1500);
  const paint = fit => { const box = $('#gmapbox'); if (!box) return; G.mapReady(box, ok => { if (ok) M.plan({ areas: P.areas, branches: P.branches.map(b => b.branch), chosen: W.assets, rest, fit, onPick: G.pickAsset }); else box.innerHTML = `<div class="gx-schem">${esc(v.mapNote || 'The map is unavailable, the plan below is complete.')}</div>`; }); };
  paint(true); $('#gpfit').onclick = () => paint(true); $('#gqatar').onclick = () => M.fitQatar();
  $$('[data-pa]').forEach(r => r.querySelector('b').onclick = () => G.pickAsset(r.dataset.pa));
  $('#gpsave').onclick = () => G.save('plan');
  $('#gpdeep').onclick = () => G.analyse(W.assets.slice(0, 40).map(x => ({ id: x.id, name: x.name, lat: x.lat, lon: x.lon, vendor: x.vendor, format: x.format })));
  $('#gpcsv').onclick = () => { const rows = [['Rank', 'Asset', 'Supplier', 'Format', 'Latitude', 'Longitude', 'Nearest branch', 'Distance m', 'Area audience fit', 'People in area (estimate)', 'Status', 'Checks'], ...W.assets.map((x, i) => [i + 1, x.name || x.id, x.vendor, x.format, x.lat, x.lon, x.branchName, x.distanceM, areaOf(x.area).score, areaOf(x.area).population, x.status, x.checks.map(c => (c.ok ? 'OK: ' : 'Check: ') + c.label).join(' | ')])];
    C.download(`geo-plan-${P.q.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}.csv`, C.csv(rows)); };
};

/* ===== 1. Map & Analysis ===== */
T.map = (el, G) => {
  const { v, C, M } = G; if (!v.result) return browse(el, G);
  const res = v.result, rows = G.ranked(), r = G.current(), many = rows.length > 1, [bl, bc] = C.band(r.score.value), L = v.layers, z = r.official;
  const placeList = v.placesFor(r), cats = [...new Set(placeList.map(x => x.c))], counted = r.score.contributions.reduce((n, c) => n + (c.count || 0), 0);
  const circ = 2 * Math.PI * 52, sv = r.score.value, opp = C.opportunity(r, v.objective, v.routes[r.site.id], opx(G, r));
  const sub = { overview: ovw, audience: aud, pois: poi, official: off, score: scr }, tabs = [['overview', 'Overview'], ['audience', 'Audience'], ['pois', 'POIs'], ['official', 'Official Data'], ['score', 'Score']];
  function ovw() { return `<div class="gx-tiles"><div><b>${z ? num(z.population) : r.municipalityContext ? num(r.municipalityContext.population) : 'Not available'}</b><small>${z ? 'Zone population ' + esc(z.year) : r.municipalityContext ? esc(r.municipalityContext.name) + ' municipality, census 2020 (no zone matched)' : 'Zone population'}</small></div><div><b>${counted ? counted : 'Unknown'}</b><small>Places within ${res.radius} m</small></div><div><b>${r.pressure ? C.km(r.pressure.nearestM) : '–'}</b><small>Nearest competitor</small></div><div><b>${Math.round(r.score.coverage * 100)}%</b><small>Evidence coverage</small></div></div>
    <div class="gx-rowl"><span>Audience</span><b>${esc(res.recipe.label)}</b></div><div class="gx-rowl"><span>Catchment radius (straight line)</span><b>${C.km(r.radius || res.radius)}${res.catchment && res.catchment.mode === 'auto' ? ' · chosen for you' : ''}</b></div>${r.populationEstimate ? `<div class="gx-rowl" title="${esc(r.populationEstimate.method)}"><span>People in the catchment <span class="gx-pill warn">Estimate</span></span><b>about ${num(r.populationEstimate.estimate)} (${num(r.populationEstimate.low)} to ${num(r.populationEstimate.high)})</b></div>` : ''}<div class="gx-rowl"><span>Official zone</span><b>${z ? esc(z.zone.split('/')[0]) : 'Not matched'}</b></div><div class="gx-rowl"><span>Confidence</span><b>${r.confidence}</b></div>`; }
  function aud() { return `<div class="gx-stack">${res.recipe.factors.map(f => `<i style="flex:${f.w};background:${M.color(res, f.cat)}" title="${esc(G.meta.categories[f.cat])} ${f.w}"></i>`).join('')}</div><div class="gx-leg">${legend(G, res)}</div><p class="gx-fine">Weights are planning assumptions; change them in Audience Insights.</p>${r.score.contributions.map(c => `<div class="gx-bar2"><span>${esc(c.label)}</span><div><i style="width:${c.normalized == null ? 0 : Math.round(c.normalized * 100)}%;background:${M.color(res, c.cat)}"></i></div><b>${c.normalized == null ? '–' : Math.round(c.normalized * 100)}</b></div>`).join('')}`; }
  function poi() { const pk = v.places[r.site.id + ':' + (r.radius || res.radius)]; return r.score.contributions.map(c => `<div class="gx-li"><span><i style="background:${M.color(res, c.cat)}"></i>${esc(c.label)}</span><b>${c.count == null ? 'Unknown' : (c.capped ? '≥ ' : '') + c.count}</b><small>${C.km(r.features[c.cat] && r.features[c.cat].nearestM)}</small></div>`).join('') + `<p class="gx-fine">${pk && pk.loading ? 'Loading nearest distances…' : 'Counts are exact where Google Places Aggregate answered.'}</p>`; }
  function off() { const mu = r.municipalityContext; return z ? `<div class="gx-tiles"><div><b>${num(z.population)}</b><small>Population ${esc(z.year)}</small></div><div><b>${num(z.areaKm2, 1)} km²</b><small>Area</small></div><div><b>${num(z.densityPerKm2)}</b><small>Density per km²</small></div><div><b>${z.change ? (z.change.pct >= 0 ? '+' : '') + z.change.pct + '%' : '–'}</b><small>${z.change ? 'vs ' + esc(z.change.sinceYear) : 'Change unknown'}</small></div></div><p class="gx-fine">Whole zone (${esc(z.zone)}), not this catchment. <a href="${esc(z.url)}" target="_blank" rel="noopener">Qatar Open Data</a></p>` : mu ? `<div class="gx-tiles"><div><b>${num(mu.population)}</b><small>${esc(mu.name)} · census ${mu.year}</small></div><div><b>${num(mu.density)}</b><small>Density per km²</small></div>${mu.population2010 ? `<div><b>${mu.population >= mu.population2010 ? '+' : ''}${Math.round(100 * (mu.population - mu.population2010) / mu.population2010)}%</b><small>vs 2010</small></div>` : ''}<div><b>${num(mu.areaKm2)} km²</b><small>Area</small></div></div><p class="gx-fine">Whole municipality, not this catchment. Add a zone for a finer level. <a href="${esc(mu.url)}" target="_blank" rel="noopener">Qatar Open Data</a></p>` : `<p class="gx-fine">${esc(r.officialNote || 'No official zone matched.')}</p>`; }
  function scr() { return sv == null ? '<p class="gx-fine">No score yet: no surrounding-place data was available.</p>' : `<div class="gx-gauge"><svg viewBox="0 0 130 130"><circle cx="65" cy="65" r="52" class="bg"/><circle cx="65" cy="65" r="52" class="fg ${bc}" stroke-dasharray="${sv / 100 * circ} ${circ}" transform="rotate(-90 65 65)"/></svg><div><b>${sv}</b><small>/100</small></div></div><span class="gx-pill ${bc} c">${bl}</span><p class="gx-fine">Audience fit for ${esc(res.recipe.label)}. ${opp.status === 'no-objective' ? 'No objective is set, so there is no opportunity index: this is a description of the place.' : opp.status === 'insufficient' ? 'Not enough evidence for an opportunity index under ' + esc(C.objLabel(v.objective)) + '.' : 'Opportunity index for ' + esc(C.objLabel(v.objective)) + ': ' + opp.value + ' (range ' + opp.low + ' to ' + opp.high + ').'}</p>`; }

  el.innerHTML = coverageNote(res) + `<div class="gx-top"><div class="gx-map card"><div class="gx-mapbox" id="gmapbox"></div>
      <div class="gx-ctl"><div class="gx-seg" id="gtype"><button data-mt="roadmap" class="${v.mapType === 'roadmap' ? 'on' : ''}">Map</button><button data-mt="hybrid" class="${v.mapType === 'hybrid' ? 'on' : ''}">Satellite</button></div><button class="btn xs" id="gfit">${I('target')}Fit selection</button><button class="btn xs" id="gqatar">Qatar</button>${many ? `<button class="btn xs ${v.view === 'all' ? 'on' : ''}" id="gall">All sites</button>` : ''}${!v.places[r.site.id + ':' + (r.radius || res.radius)] && v.st.google ? `<button class="btn xs" id="gloadpl" title="Looks up nearby places once and caches the coordinates">${I('map-pin')}Load places</button>` : ''}</div>
      <div class="gx-layers"><b>Layers</b><label><input type="checkbox" data-l="sites" ${L.sites ? 'checked' : ''}> ${many ? 'OOH sites' : 'Site'}</label><label><input type="checkbox" data-l="rings" ${L.rings ? 'checked' : ''}> Catchments</label><label><input type="checkbox" data-l="places" ${L.places ? 'checked' : ''}> Competitors &amp; POIs</label>${G.clients().length ? `<label><input type="checkbox" data-l="clients" ${L.clients ? 'checked' : ''}> Client locations</label>` : ''}<label><input type="checkbox" data-l="inv" ${L.inv ? 'checked' : ''}> OOH assets (click one to analyse it)</label><label><input type="checkbox" data-l="lock" ${L.lock !== false ? 'checked' : ''}> Highlight Qatar</label><label><input type="checkbox" data-l="muni" ${L.muni ? 'checked' : ''}> Municipalities (population)</label>
        ${cats.map(c => `<label class="sub"><input type="checkbox" data-lc="${c}" ${L.off[c] ? '' : 'checked'}><i style="background:${M.color(res, c)}"></i>${esc(G.meta.categories[c] || c)}</label>`).join('')}<small>Zone boundaries are not published, so zones are matched by name and not drawn.</small>${ctxLayers(G)}</div></div>
    <div class="gx-card gx-sitec"><div class="gx-sh"><div><h3 dir="auto">${esc(r.site.name || r.site.id)}</h3><span>${[r.site.vendor, r.site.format, r.site.road, r.site.municipality].filter(Boolean).map(esc).join(' · ') || 'Selected location'}</span><span>${r.site.lat.toFixed(4)}, ${r.site.lon.toFixed(4)}${r.site.id && r.site.id !== 'site' ? ' · ' + esc(r.site.id) : ''}</span></div><span class="gx-pill ${bc}">${bl}</span></div>
      <div class="gx-subtabs">${tabs.map(([k, l]) => `<button class="${v.sp === k ? 'on' : ''}" data-sp="${k}">${l}</button>`).join('')}</div><div id="gsp">${sub[v.sp]()}</div>
      <div class="gx-acts"><button class="btn sm" id="gsv">${I('save')}Save analysis</button>${many ? `<small>${rows.indexOf(r) + 1} of ${rows.length} · click a site on the map</small>` : ''}</div></div></div>
    <div class="gx-row4">
      <div class="gx-card"><h4>Official Qatar data ${z ? `<small>${esc(z.zone.split('/')[0])}</small>` : ''}</h4>${off()}<button class="gx-link" data-go-tab="official">View all ${I('chevron-right')}</button></div>
      <div class="gx-card"><h4>Nearby POIs <small>${res.radius} m</small></h4>${poi()}</div>
      <div class="gx-card"><h4>Competitor density</h4>${r.pressure ? `<div class="gx-big">${r.pressure.capped ? '≥ ' : ''}${r.pressure.count}<small>${esc(r.pressure.label.toLowerCase())} within ${C.km(res.radius)}</small></div><div class="gx-meter"><i style="width:${Math.min(100, r.pressure.count * 5)}%"></i></div><div class="gx-li"><span>Nearest</span><b>${C.km(r.pressure.nearestM)}</b></div><button class="gx-link" data-go-tab="comp">Competitors &amp; POIs ${I('chevron-right')}</button>` : `<p class="gx-fine">Choose a competitor category above to see how crowded the catchment is.</p>`}</div>
      <div class="gx-card"><h4>${opp.status === 'no-objective' ? 'Audience fit' : 'Opportunity'} <small>${esc(opp.status === 'no-objective' ? res.recipe.label : C.objLabel(v.objective))}</small></h4>${scr()}${opp.parts.filter(p => p.value != null).map(p => `<div class="gx-bar2"><span>${esc(p.label)}</span><div><i style="width:${Math.round(p.value * 100)}%"></i></div><b>${Math.round(p.value * 100)}</b></div>`).join('')}<small class="gx-fine">Evidence coverage ${Math.round((opp.status === 'no-objective' ? r.score.coverage : opp.coverage) * 100)}%${opp.seasonAdj ? ` · timing ${pct(opp.seasonAdj)} (${esc(res.season.active.filter(a => a.effect).map(a => a.name).join(', '))})` : ''}</small></div></div>
    <div class="gx-row2"><div class="gx-card"><h4>Recommended next steps <small>rule-based</small></h4><ul class="gx-list">${(res.recommendations || []).map(x => `<li><span class="gx-pill ${x.priority === 'Do now' ? 'ok' : ''}">${x.priority}</span> ${esc(x.action)}<small>${esc(x.rationale)}${ev(res, x.evidence_refs)}</small></li>`).join('')}</ul>${aiBlock(G)}</div>
      <div class="gx-card">${sources(G)}</div></div>
    <div class="gx-row2">${timing(G)}${oohNear(G, r)}</div>`;
  $$('[data-sp]').forEach(b => b.onclick = () => { v.sp = b.dataset.sp; T.map(el, G); });
  $$('[data-near]').forEach(b => b.onclick = () => G.pickAsset(b.dataset.near));
  $$('[data-ctx]').forEach(c => c.onchange = async () => { c.disabled = true; await G.toggleCtx(c.dataset.ctx, c.checked); T.map(el, G); });
  $$('[data-go-tab]').forEach(b => b.onclick = () => { v.tab = b.dataset.goTab; G.show(); });
  $$('[data-l]').forEach(c => c.onchange = () => { L[c.dataset.l] = c.checked; if (c.dataset.l === 'muni') return muni(); if (c.dataset.l === 'lock') return lock(); paintMap(); });
  $$('[data-lc]').forEach(c => c.onchange = () => { L.off[c.dataset.lc] = !c.checked; paintMap(); });
  $$('[data-mt]').forEach(b => b.onclick = () => { v.mapType = b.dataset.mt; M.setType(v.mapType); $$('[data-mt]').forEach(x => x.classList.toggle('on', x === b)); });
  const all = $('#gall'); if (all) all.onclick = () => { v.view = v.view === 'all' ? 'site' : 'all'; all.classList.toggle('on', v.view === 'all'); paintMap(true); };
  $('#gfit').onclick = () => paintMap(true); $('#gqatar').onclick = () => M.fitQatar();
  const lp = $('#gloadpl'); if (lp) lp.onclick = () => { lp.disabled = true; G.loadPlaces(); };
  $('#gsv').onclick = G.save; wireAi(G);
  paintMap(true);
  async function lock() { try { v.muniGeo = v.muniGeo || await PI.api('GET', 'geo/boundaries/municipalities'); } catch (_) { return; } if (M.map) M.setMask(v.muniGeo, v.layers.lock !== false); }
  async function muni() { try { v.muniGeo = v.muniGeo || await PI.api('GET', 'geo/boundaries/municipalities'); } catch (_) { PI.toast('Municipality boundaries are unavailable right now'); L.muni = false; } if (M.map) M.setMuni(v.muniGeo, L.muni); }
  function paintMap(fit) {
    const box = $('#gmapbox'); if (!box) return;
    G.mapReady(box, ok => { if (ok) { M.update({ res, r, sites: rows, places: placeList, clients: G.clients().map(p => ({ lat: p.lat, lon: p.lon, name: p.name })), inv: G.oohAll(), near: G.oohNear(r), ctx: G.ctxPoints(r), layers: L, fit: fit ? (v.view === 'all' ? 'all' : 'site') : null, onSelect: G.select, onPickAsset: G.pickAsset }); if (L.muni && v.muniGeo) M.setMuni(v.muniGeo, true); lock(); } else { box.innerHTML = M.schematic(res, r, v, many, v.view === 'all') + (v.mapNote ? `<div class="gx-schem">${esc(v.mapNote)}</div>` : ''); box.querySelectorAll('[data-site]').forEach(g => g.onclick = () => G.select(g.dataset.site)); } });
  }
};

function timing(G) {
  const { v } = G, se = v.result.season; if (!se) return '';
  const row = a => `<li><b>${esc(a.name)}</b>${a.effect ? ` <span class="gx-pill ${a.effect > 0 ? 'ok' : 'warn'}">${pct(a.effect)} for ${esc(v.result.recipe.label.toLowerCase())}</span>` : ''}<small>${esc(a.note)}${a.dayparts ? ' Best reached: ' + esc(a.dayparts.toLowerCase()) + '.' : ''}${a.approx ? ' Dates approximate.' : ''}${a.inDays != null ? ' Starts in ' + a.inDays + ' days.' : ''}</small></li>`;
  return `<div class="gx-card"><h4>Timing <small>rule-based, ${esc(se.date)}</small></h4><ul class="gx-list">${se.active.filter(a => a.effect).concat(se.upcoming.filter(a => a.effect)).slice(0, 5).map(row).join('') || '<li>No seasonal effect is expected for this audience in the next three months.</li>'}</ul>${se.peak ? `<p class="gx-fine">Strongest window ahead: <b>${esc(se.peak.name)}</b>${se.peak.inDays ? ' in ' + se.peak.inDays + ' days' : ' now'}.</p>` : ''}<p class="gx-fine">${esc(se.method)}</p></div>`;
}
function oohNear(G, r) {
  const list = G.oohNear(r); if (!G.oohAll().length) return '<div class="gx-card"><h4>OOH assets in the catchment</h4><p class="gx-fine">No OOH inventory is loaded. Choose one above to see which assets sit inside this catchment.</p></div>';
  const by = {}; list.forEach(x => { by[x.vendor || 'Unknown supplier'] = (by[x.vendor || 'Unknown supplier'] || 0) + 1; });
  return `<div class="gx-card"><h4>OOH assets in the catchment <small>${list.length} within ${G.C.km(r.radius || G.v.result.radius)}</small></h4>${list.length ? `<p class="gx-fine" style="margin-top:0">${Object.entries(by).map(([k, n]) => esc(k) + ' ' + n).join(' · ')}</p><ul class="gx-list">${list.slice(0, 8).map(x => `<li><button class="gx-link" data-near="${esc(x.id)}"><b dir="auto">${esc(x.name || x.id)}</b></button><small>${[x.vendor, x.format, G.C.km(x.d)].filter(Boolean).map(esc).join(' · ')} · click to analyse it</small></li>`).join('')}</ul>` : '<p class="gx-fine">None of the loaded OOH assets sit inside this catchment.</p>'}</div>`;
}
const CTX_NOTE = 'Draws the matching places around the selected site. Uses Google Places once per category, then reuses the stored result.';
function ctxLayers(G) {
  const { v } = G; if (!v.st.google) return '';
  return `<div class="gx-ctxl"><b>Audience context</b>${G.CTX.map(g => `<label class="sub" title="${esc(CTX_NOTE)}"><input type="checkbox" data-ctx="${g.id}" ${v.ctxOn && v.ctxOn[g.id] ? 'checked' : ''}><i style="background:${g.color}"></i>${esc(g.label)}</label>`).join('')}<small>${esc(CTX_NOTE)}</small></div>`;
}

function sources(G) {
  const res = G.v.result;
  const pl = res.planning, fresh = pl.requested - pl.cached;
  return `<h4>Sources &amp; methodology</h4><p class="gx-fine" style="margin-top:0">This run: ${fresh} new Google request${fresh === 1 ? '' : 's'}, ${pl.cached} reused from earlier results.</p><details><summary>Evidence (${res.evidence.length})</summary><ul class="gx-list">${res.evidence.map(e => `<li><b>${esc(e.id)} · ${esc(e.kind)}</b> ${esc(e.text)}<small>${esc([e.source, e.retrieved, e.cached ? 'cached' : ''].filter(Boolean).join(' · '))}</small></li>`).join('')}</ul></details>
    <details><summary>How scores are made</summary><p class="gx-fine">Audience fit = 100 × Σ(weight × place density) ÷ Σ(weights with evidence). Place density is the count within the catchment, saturating at 20. Missing categories are left out and lower the coverage figure. Opportunity combines audience fit, official area context, competitor gap and (when measured) drive time, with weights set by the objective. Evidence classes: observed (providers, official data), calculated (code), rule-based (recipes), AI-interpreted (only when you ask).</p></details>
    <ul class="gx-lim">${res.limits.map(l => `<li>${esc(l)}</li>`).join('')}</ul>`;
}
function aiBlock(G) {
  const v = G.v, a = v.ai;
  const body = !a ? '' : a.busy ? '<p class="gx-fine"><span class="spin" style="vertical-align:-2px;margin-right:8px"></span>Reading the evidence</p>' : !a.ok ? `<p class="gx-fine">AI interpretation is unavailable. Deterministic Geo Intelligence remains available. (${esc(a.error)})</p>`
    : `<h5>AI-interpreted</h5><ul class="gx-list">${a.findings.map(f => `<li><span class="gx-pill">${f.classification}</span> ${esc(f.statement)}<small>${f.confidence} · ${esc(f.refs.join(', '))}</small></li>`).join('')}${a.audience.map(x => `<li><b>${esc(x.archetype)}</b> ${esc(x.rationale)}<small>${esc(x.refs.join(', '))}</small></li>`).join('')}${a.actions.map(x => `<li><span class="gx-pill ${x.priority === 'Do now' ? 'ok' : ''}">${x.priority}</span> ${esc(x.action)}<small>${esc(x.rationale)}${x.validation ? ' · to validate: ' + esc(x.validation) : ''}</small></li>`).join('')}</ul>${a.dropped ? `<p class="gx-fine">${a.dropped} AI statement${a.dropped > 1 ? 's' : ''} left out because they could not be matched to the evidence.</p>` : ''}`;
  const can = S.me && S.me.caps && S.me.caps.ai;
  return `<div class="gx-aibox"><button class="btn sm" id="gexplain" ${can && !(a && a.busy) ? '' : 'disabled'}>${I('sparkles')}Explain findings with AI</button>${can ? '<small>Runs once, only when you press it. Uses credits.</small>' : '<small>AI interpretation is not configured.</small>'}${body}</div>`;
}
function wireAi(G) { const b = $('#gexplain'); if (b) b.onclick = G.explain; }

/* ===== 2. Official Data ===== */
T.official = async (el, G) => {
  const v = G.v, C = G.C;
  el.innerHTML = '<div class="gx-empty"><span class="spin"></span></div>';
  let o, reg; try { o = v.qd || (v.qd = await PI.api('GET', 'geo/qatar/overview')); reg = v.reg || (v.reg = (await PI.api('GET', 'geo/qatar/registry')).datasets); } catch (e) { el.innerHTML = `<div class="notice err">${I('circle-alert')}<div>Official Qatar data is temporarily unavailable.</div></div>`; return; }
  const topic = v.topic || 'all', ok = x => x && !x.error;
  const sum = a => (a || []).reduce((x, y) => x + y, 0), yr = ok(o.age) ? o.age.year : null;
  const kpi = (label, val, sub) => `<div class="gx-kpi"><small>${label}</small><b>${val}</b><span>${sub}</span></div>`;
  const kpis = [
    ok(o.age) && kpi('Population (estimate)', num(sum(o.age.female) + sum(o.age.male)), 'Qatar · ' + yr),
    ok(o.municipalities) && kpi('Largest municipality', esc(o.municipalities.rows[0].name), num(o.municipalities.rows[0]['2020'].population) + ' · census 2020'),
    ok(o.employment) && kpi('Economically active', num(sum(o.employment.y2020)), 'Qatar · census 2020'),
    ok(o.employment) && o.employment.nationality && kpi('Qatari share of workforce', o.employment.nationality.qatariShare + '%', 'Qatar · census ' + o.employment.nationality.year + ' · economically active, national only') ,
    ok(o.housing) && kpi('Housing units', num(sum(o.housing.y2020)), 'Qatar · census 2020'),
    ok(o.zones) && kpi('Densest large zone', esc(o.zones.rows[0].label), num(o.zones.rows[0].density) + ' per km² · observed ' + o.zones.year),
    v.result && G.current().official && kpi('Selected site zone', esc(G.current().official.zone.split('/')[0]), num(G.current().official.population) + ' · ' + G.current().official.year)].filter(Boolean);
  const card = (id, title, d, note, topics) => (topic === 'all' || topics.includes(topic)) ? `<div class="gx-card"><h4>${title}</h4><p class="gx-fine" style="margin:0 0 6px">${note}</p><div id="${id}">${ok(d) ? '' : '<div class="gx-empty small">Not available right now.</div>'}</div>${src(d)}</div>` : '';
  el.innerHTML = `<div class="gx-oh"><div><b>${v.result ? esc(G.current().site.name || 'Selected site') : 'Qatar'}</b><small>${reg.length} official datasets · latest published periods shown on each chart</small></div>
      <div class="gx-seg" id="gtopic">${[['all', 'All'], ['Population', 'Population'], ['Employment', 'Employment'], ['Housing', 'Housing']].map(([k, l]) => `<button data-tp="${k}" class="${topic === k ? 'on' : ''}">${l}</button>`).join('')}</div></div>
    <div class="notice info">${I('info')}<div>Official figures cover whole zones, municipalities or the country, never a radius around a site. They are context, not a count inside the catchment.</div></div>
    <div class="gx-kpis">${kpis.join('')}</div>
    <div class="gx-grid2">${card('qd1', 'Population by municipality', o.municipalities, 'Census 2010 and 2020 · municipality', ['Population'])}${card('qd2', 'Largest zones by population', o.zones, (ok(o.zones) ? o.zones.year + ' observations' : 'Latest observations') + ' · by official zone', ['Population'])}${card('qd3', 'Age profile', o.age, 'Estimated population by age group and gender · national', ['Population'])}${card('qd5', 'Employment by employer sector', o.employment, 'Economically active population, census 2010 and 2020 · national', ['Employment'])}${card('qd4', 'Housing units by type', o.housing, 'Census 2010 and 2020 · national', ['Housing'])}</div>
    ${cmpAreas(o, v)}
    <div class="gx-card" style="margin-top:14px"><h4>Sources &amp; methodology</h4><table class="gx-t"><thead><tr><th>Dataset</th><th>Topic</th><th>Geography</th><th>Observation period</th><th>Source updated</th></tr></thead><tbody>${reg.map(d => `<tr><td><a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener">${esc(d.title)}</a></td><td>${d.topic}</td><td>${d.geographyLevel}</td><td>${esc(d.referencePeriod)}</td><td>${esc((d.updatedAt || '').slice(0, 10)) || '–'}</td></tr>`).join('')}</tbody></table></div>
    <div class="gx-card" style="margin-top:14px"><h4>Explore the portal</h4><div class="gx-inline"><input id="qs" placeholder="e.g. tourism, schools, transport"><button class="btn sm" id="qgo">${I('search')}Search</button></div><div id="qres"></div><div id="qprev"></div></div>`;
  const chart = (id, cfg, d) => { const e = $('#' + id); if (e && ok(d)) PI.chart(e, cfg); };
  if (ok(o.municipalities)) { const r = o.municipalities.rows; chart('qd1', { type: 'hbar', x: r.map(x => x.name), series: [{ name: '2020', values: r.map(x => x['2020'].population) }] }, o.municipalities); }
  if (ok(o.zones)) chart('qd2', { type: 'hbar', x: o.zones.rows.map(x => x.label), series: [{ name: 'Population', values: o.zones.rows.map(x => x.population) }] }, o.zones);
  if (ok(o.age)) chart('qd3', { type: 'bar', x: o.age.groups, series: [{ name: 'Females', values: o.age.female }, { name: 'Males', values: o.age.male }] }, o.age);
  if (ok(o.employment)) chart('qd5', { type: 'hbar', x: o.employment.sectors.map(short), series: [{ name: '2020', values: o.employment.y2020 }] }, o.employment);
  if (ok(o.housing)) chart('qd4', { type: 'hbar', x: o.housing.types.map(short), series: [{ name: '2020', values: o.housing.y2020 }] }, o.housing);
  $$('[data-tp]').forEach(b => b.onclick = () => { v.topic = b.dataset.tp; T.official(el, G); });
  wireCmp(o, v);
  const find = async () => { const r = $('#qres'); r.innerHTML = '<span class="spin"></span>'; try { const x = (await PI.api('GET', 'geo/qatar/search?q=' + encodeURIComponent($('#qs').value))).results; r.innerHTML = x.length ? `<div class="gx-listbox">${x.map(d => `<button class="gx-li gx-sv" data-d="${esc(d.id)}"><span>${esc(d.title)}</span><small>${esc((d.modified || '').slice(0, 10))}</small></button>`).join('')}</div>` : '<p class="gx-fine">No datasets found.</p>'; } catch (e) { r.innerHTML = `<p class="gx-fine">${esc(e.message)}</p>`; }
    $$('[data-d]').forEach(b => b.onclick = async () => { const pv = $('#qprev'); pv.innerHTML = '<span class="spin"></span>'; try { const d = await PI.api('GET', 'geo/qatar/dataset?id=' + encodeURIComponent(b.dataset.d)); pv.innerHTML = `<h5>${esc(d.title)}</h5>${src({ ...d, level: 'the dataset' })}<div class="gx-tw">${PI.tableHTML(d.rows.map(r => Object.fromEntries(d.fields.slice(0, 8).map(f => [f.label, r[f.name] == null ? '' : String(r[f.name]).slice(0, 60)]))), 20)}</div>`; } catch (e) { pv.innerHTML = `<p class="gx-fine">${esc(e.message)}</p>`; } }); };
  $('#qgo').onclick = find; $('#qs').onkeydown = e => { if (e.key === 'Enter') find(); };
};
// Compare areas: only areas of one geography level and one reference period can be compared.
function cmpItems(o, lvl) { const d = lvl === 'municipality' ? o.municipalities : o.zones; return lvl === 'municipality' ? d.rows.map(x => ({ key: 'muni:' + x.name + ':2020', label: x.name, year: '2020 census', ...(x['2020'] || {}) })) : d.all; }
function cmpAreas(o, v) {
  const lvl = v.cmpLevel || 'municipality', d = lvl === 'municipality' ? o.municipalities : o.zones;
  if (!d || d.error) return '';
  // Areas are selected by an official key (zone number + observation year), never by display name, so same-name zones stay separate.
  const items = cmpItems(o, lvl), pick = (v.cmpAreas || []).map(k => items.find(x => x.key === k)).filter(Boolean), metric = v.cmpMetric || 'population';
  return `<div class="gx-card" style="margin-top:14px"><h4>Compare areas <small>${lvl === 'municipality' ? '2020 census observations' : esc(d.year) + ' observations, by official zone number'}</small></h4>
    <div class="gx-inline"><div class="gx-seg" id="cmplvl" role="group" aria-label="Geography level"><button data-cl="municipality" aria-pressed="${lvl === 'municipality'}" class="${lvl === 'municipality' ? 'on' : ''}">Municipalities</button><button data-cl="zone" aria-pressed="${lvl === 'zone'}" class="${lvl === 'zone' ? 'on' : ''}">Zones</button></div><div class="gx-seg" id="cmpmet" role="group" aria-label="Measure"><button data-cm="population" aria-pressed="${metric === 'population'}" class="${metric === 'population' ? 'on' : ''}">Population</button><button data-cm="density" aria-pressed="${metric === 'density'}" class="${metric === 'density' ? 'on' : ''}">Density</button></div></div>
    <p class="gx-fine">Pick 2 to 5 areas. Municipalities and zones are different geography levels, so they are compared separately.${lvl === 'zone' ? ' Zones that share a name are told apart by their zone number.' : ''}</p>
    <div class="gx-chips" role="group" aria-label="Areas to compare">${items.slice(0, 100).map(x => { const on = pick.includes(x); return `<label class="${on ? 'on' : ''}" title="${esc(x.label)}"><input type="checkbox" data-ca="${esc(x.key)}" ${on ? 'checked' : ''}>${esc(x.label)}</label>`; }).join('')}</div>
    ${pick.length >= 2 ? `<div id="cmpch"></div><div class="gx-tw"><table class="gx-t"><thead><tr><th>Area</th><th>Observed</th><th>Population</th><th>Density per km²</th></tr></thead><tbody>${pick.map(x => `<tr><td>${esc(x.label)}</td><td>${esc(x.year)}</td><td>${x.population == null ? 'Unknown' : num(x.population)}</td><td>${x.density == null ? 'Unknown' : num(x.density, 1)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="gx-fine">Select at least two areas.</p>'}</div>`;
}
function wireCmp(o, v) {
  const el = $('#gxb'), re = () => { const holder = el.querySelector('.gx-card:has(#cmplvl)'); if (holder) { const t = document.createElement('div'); t.innerHTML = cmpAreas(o, v); holder.replaceWith(t.firstElementChild); wireCmp(o, v); } };
  $$('[data-cl]').forEach(b => b.onclick = () => { v.cmpLevel = b.dataset.cl; v.cmpAreas = []; re(); });
  $$('[data-cm]').forEach(b => b.onclick = () => { v.cmpMetric = b.dataset.cm; re(); });
  $$('[data-ca]').forEach(c => c.onchange = () => { const s = new Set(v.cmpAreas || []); c.checked ? s.add(c.dataset.ca) : s.delete(c.dataset.ca); if (s.size > 5) { s.delete(c.dataset.ca); PI.toast('Compare up to 5 areas'); } v.cmpAreas = [...s]; re(); });
  const ch = $('#cmpch'); if (ch) { const met = v.cmpMetric || 'population', items = cmpItems(o, v.cmpLevel || 'municipality'), rows = (v.cmpAreas || []).map(k => items.find(x => x.key === k)).filter(Boolean); PI.chart(ch, { type: 'hbar', x: rows.map(r => r.label), series: [{ name: met, values: rows.map(r => r[met] || 0) }] }); }
}

// Team-tuned weights for the selected audience (only offered after enough adjustments; never applied automatically).
function tunedBlock(G) {
  const { v, meta, BR } = G, rec = meta.recipes.find(r => r.id === v.recipe); if (!rec) return '';
  const tu = BR.tuned(v.brain, v.recipe, Object.fromEntries(rec.factors.map(f => [f.cat, f.w]))), have = (v.brain.weightVotes[v.recipe] || { n: 0 }).n;
  return tu ? `<p class="gx-fine" style="margin-top:12px">Team adjustments (${tu.votes}) suggest: ${rec.factors.map(f => `${esc(meta.categories[f.cat])} ${f.w} → <b>${tu.weights[f.cat]}</b>`).join(' · ')}. <button class="btn xs" id="gtuned" data-w='${JSON.stringify(tu.weights)}'>Use team weights</button></p>` : `<p class="gx-fine" style="margin-top:12px">The team has made ${have} weight adjustment${have === 1 ? '' : 's'} for this audience. A suggestion appears after ${BR.MIN_VOTES}.</p>`;
}
// What the Geo brain has learned, in plain words, with the way to reset it.
function brainCard(G) {
  const { v, meta, BR } = G, b = v.brain, labels = G.brainLabels(), ins = BR.insights(b, labels), tunes = meta.recipes.map(r => ({ r, tu: BR.tuned(b, r.id, Object.fromEntries(r.factors.map(f => [f.cat, f.w]))) })).filter(x => x.tu);
  return `<div class="gx-card"><h4>Geo brain <small>${b.runs} analyses · shared by ${S.clientId ? 'this client' : 'the team'}</small></h4>
    ${ins.length ? `<ul class="gx-list">${ins.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<p class="gx-fine">Nothing learned yet. Each analysis teaches it which places, audiences and catchments the team uses.</p>'}
    ${tunes.length ? `<h5>Suggested weights from team adjustments</h5><ul class="gx-list">${tunes.map(({ r, tu }) => `<li><b>${esc(r.label)}</b> (${tu.votes} adjustments): ${r.factors.map(f => `${esc(meta.categories[f.cat])} ${f.w} → ${tu.weights[f.cat]}`).join(', ')}</li>`).join('')}</ul>` : ''}
    <p class="gx-fine">It learns what planners look at and how they weigh things, not campaign results. Searched places come back without another lookup, "Your usual" appears after 3 analyses, and suggested weights are used only when someone chooses them. Scores never change on their own.</p>
    ${b.runs ? `<button class="btn xs" id="gbreset">Reset the brain</button>` : ''}</div>`;
}
// How the analysed sites were chosen, shown wherever a ranking appears: eligible, ranked locally, enriched, left out.
function coverageNote(res) {
  const s = res && res.selection; if (!s || !(s.inventory > 1)) return '';
  return `<div class="gx-cov" role="note"><b>${num(s.inventory)}</b> in the inventory → <b>${num(s.eligible)}</b> in scope → <b>${num(s.prescreened)}</b> ranked locally at no cost → <b>${num(s.enriched)}</b> analysed with Google${s.notEnriched ? ` → <b>${num(s.notEnriched)}</b> not analysed` : ''}.
    <details><summary>How they were chosen</summary><p>${esc(s.rule)}${s.scope ? ' ' + esc(s.scope) : ''}</p>${Object.keys(s.excluded || {}).length ? `<ul>${Object.entries(s.excluded).map(([k, n]) => `<li>${num(n)}: ${esc(k)}</li>`).join('')}</ul>` : ''}${s.caveat ? `<p>${esc(s.caveat)}</p>` : ''}</details></div>`;
}
// The words that tell one advertising face from another: code, circuit, supplier, format. Used for buttons and accessible names.
const faceName = r => [r.id, r.circuit ? 'circuit ' + r.circuit : '', r.vendor, r.format, r.screen_type].filter(Boolean).join(' · ');
const spotOf = r => r.lat.toFixed(5) + ':' + r.lon.toFixed(5);
// Browse an inventory before analysing anything. Faces that share one spot are one dot on the map and separate rows in the list,
// so each can be chosen by pointer or keyboard.
function browse(el, G) {
  const { v, M } = G, rows = v.inv ? G.filtered() : [];
  if (!v.inv || !rows.length) { el.innerHTML = `<div class="gx-empty">${I('map-pin')}<b>${v.inv && v.inv === G.BUILTIN && !v.builtin ? 'Loading the assets' : v.inv ? 'No assets match those filters' : 'Nothing is selected yet'}</b><span>${v.inv ? 'Change the supplier, medium or search filters above.' : 'Choose what you want to do at the top. The line beside the main button says what is still needed.'}</span>${v.inv ? '' : '<button class="btn sm" data-focus="#gq">Go to Where</button>'}</div>`; $$('[data-focus]').forEach(b => b.onclick = () => { const f = $(b.dataset.focus); if (f) f.focus(); }); return; }
  const sel = v.browseSel && rows.find(x => x.id === v.browseSel.id) ? v.browseSel : null, stacks = new Map(); rows.forEach(r => { const k = spotOf(r); (stacks.get(k) || stacks.set(k, []).get(k)).push(r); });
  const here = sel ? stacks.get(spotOf(sel)) : (v.browseSpot && stacks.get(v.browseSpot)) || null, list = here && here.length > 1 ? here : rows.slice(0, 60), shared = [...stacks.values()].filter(x => x.length > 1).length;
  el.innerHTML = `<div class="gx-top"><div class="gx-map card"><div class="gx-mapbox" id="gmapbox"></div><div class="gx-ctl"><div class="gx-seg" role="group" aria-label="Map type"><button data-mt="roadmap" aria-pressed="${v.mapType === 'roadmap'}" class="${v.mapType === 'roadmap' ? 'on' : ''}">Map</button><button data-mt="hybrid" aria-pressed="${v.mapType === 'hybrid'}" class="${v.mapType === 'hybrid' ? 'on' : ''}">Satellite</button></div><button class="btn xs" id="gfit">${I('target')}Fit all</button><button class="btn xs" id="gqatar">Qatar</button></div></div>
    <div class="gx-card gx-sitec"><h4>${rows.length.toLocaleString('en-US')} assets <small>${esc((v.inv === G.BUILTIN ? 'Qatar OOH assets' : (v.invs.find(i => i.id === v.inv) || {}).name) || '')}${shared ? ` · ${shared} spots hold more than one face` : ''}</small></h4>
      ${sel ? `<div class="gx-sh"><div><h3 dir="auto">${esc(sel.id)}${sel.name && sel.name !== sel.id ? ' <small>' + esc(sel.name) + '</small>' : ''}</h3><span>${[sel.vendor, sel.format, sel.screen_type].filter(Boolean).map(esc).join(' · ')}</span><span>${sel.lat.toFixed(4)}, ${sel.lon.toFixed(4)} · ${esc(sel.id)}</span><span>${esc(sel.site_description || '')}${sel.circuit ? ' · circuit ' + esc(sel.circuit) : ''}</span></div></div><button class="btn pri" id="ganasel">${I('target')}Analyse this asset</button>` : '<p class="gx-fine">Choose an asset from the list or the map.</p>'}
      <h5 id="gfacesh">${here && here.length > 1 ? `${here.length} faces at this spot: choose one` : rows.length > 60 ? 'First 60 of the list (filter above to narrow)' : 'Assets'}</h5>
      <ul class="gx-faces" aria-labelledby="gfacesh">${list.map(r => `<li><button class="gx-face ${sel && sel.id === r.id ? 'on' : ''}" data-face="${esc(r.id)}" aria-pressed="${!!(sel && sel.id === r.id)}" aria-label="${esc(faceName(r))}"><b dir="auto">${esc(r.id)}</b><small>${esc([r.circuit ? 'circuit ' + r.circuit : '', r.vendor, r.format].filter(Boolean).join(' · '))}${stacks.get(spotOf(r)).length > 1 ? ' · shares its spot' : ''}</small></button></li>`).join('')}</ul>
      ${here && here.length > 1 ? `<button class="gx-link" id="gfacesall">Show the whole list</button>` : ''}
      ${v.inv === G.FOUND ? `<p class="gx-fine">${v.found.items.length} found${v.found.saturated ? ' · some areas hit Google\'s limit of 60 per search, so there may be more' : ''}${v.found.cached ? ' · answered from the database, with no new Google request' : ''}.</p><button class="btn sm" id="gsavefound">${I('save')}Save as client locations</button>` : ''}
      <div class="gx-acts"><button class="btn sm" id="ganaall">${I('layers')}${rows.length > 40 ? `Analyse the best 40 of ${rows.length.toLocaleString('en-US')}` : `Analyse ${rows.length === 1 ? 'this asset' : 'these ' + rows.length}`}</button></div>
      <p class="gx-fine">${rows.length > 40 ? 'All ' + rows.length.toLocaleString('en-US') + ' are ranked locally first, at no Google cost, and the rule is shown before anything runs. ' : ''}Coordinates give location context only. They do not show visibility, traffic or impressions.</p></div></div>`;
  $$('[data-mt]').forEach(b => b.onclick = () => { v.mapType = b.dataset.mt; M.setType(v.mapType); $$('[data-mt]').forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', String(x === b)); }); });
  const pick = (id, focus) => { v.browseSel = rows.find(x => x.id === id) || null; v.browseSpot = v.browseSel ? spotOf(v.browseSel) : null; PI.geoBrief.readyUI(G); browse(el, G); if (focus) { const b = el.querySelector(`[data-face="${CSS.escape(id)}"]`); if (b) b.focus(); } };
  $$('[data-face]').forEach(b => b.onclick = () => pick(b.dataset.face, true));
  const fa = $('#gfacesall'); if (fa) fa.onclick = () => { v.browseSel = null; v.browseSpot = null; browse(el, G); };
  // A dot with several faces opens the list of those faces instead of guessing one.
  const draw = fit => { const box = $('#gmapbox'); G.mapReady(box, ok => { if (ok) { M.browse({ stacks: [...stacks.values()], sel, clients: G.clients(), fit, name: faceName, onSelect: st => { if (st.length === 1) return pick(st[0].id); v.browseSel = null; v.browseSpot = spotOf(st[0]); browse(el, G); const b = el.querySelector('[data-face]'); if (b) b.focus(); } }); (async () => { try { v.muniGeo = v.muniGeo || await PI.api('GET', 'geo/boundaries/municipalities'); } catch (_) { return; } if (M.map) M.setMask(v.muniGeo, v.layers.lock !== false); })(); } else box.innerHTML = '<div class="gx-empty small"><b>The map is not available</b><span>Use the list beside it. Analysis still works.</span></div>'; }); };
  draw(!sel && !v.browseSpot); $('#gfit').onclick = () => draw(true); $('#gqatar').onclick = () => M.fitQatar();
  const sf = $('#gsavefound'); if (sf) sf.onclick = async () => { const id = PI.uid(); try { await PI.saveDoc('geoooh', id, { name: v.found.query, kind: 'client', rows: G.invRows(G.FOUND).map(r => ({ id: r.id, name: r.name, lat: r.lat, lon: r.lon })), version: 1, history: [], updatedAt: Date.now(), client: S.clientId || '' }); v.clientLoc = id; PI.toast('Saved. Choose it under Client locations.'); G.refreshAll && G.refreshAll(); } catch (e) { PI.toast(e.message); } };
  const a1 = $('#ganasel'); if (a1) a1.onclick = () => G.run();
  $('#ganaall').onclick = () => { v.browseSel = null; v.browseSpot = null; G.run(); };
}

/* ===== 3. Audience Insights ===== */
T.audience = (el, G) => {
  const { v, C, M, meta } = G, res = v.result;
  const cards = meta.recipes.map(x => `<button class="gx-aud ${x.id === v.recipe ? 'on' : ''}" data-ra="${x.id}" aria-pressed="${x.id === v.recipe}"><b>${esc(x.label)}</b><small>${esc(x.blurb || '')}</small>${x.id === v.recipe && res ? `<span class="gx-pill ${C.band(G.current().score.value)[1]}">Fit ${G.current().score.value ?? 'n/a'}</span>` : `<span class="gx-fine">${x.id === v.recipe ? 'Selected' : 'Choose this audience'}</span>`}</button>`).join('');
  const cur = meta.recipes.find(x => x.id === v.recipe), rd = PI.geoBrief.ready(G), lay = (G.CTX || []).filter(g => cur && g.cats.some(c => cur.factors.some(f => f.cat === c)));
  let detail = cur ? `<div class="gx-card"><h4>${esc(cur.label)} <small>what this audience is read from</small></h4><p class="gx-fine" style="margin-top:0">Places counted around each location, heaviest first. The weights are planning assumptions you can change after a run.</p>${cur.factors.slice().sort((a, b) => b.w - a.w).map(f => `<div class="gx-bar2"><span>${esc(f.label || meta.categories[f.cat])}</span><div><i style="width:${f.w * 33}%"></i></div><b>${f.w}</b></div>`).join('')}
      <p class="gx-fine">${lay.length ? 'Suggested map layers: ' + lay.map(g => esc(g.label)).join(', ') + '. ' : ''}These places are a sign of who is likely to be around. They are not a count of people, and say nothing about any individual.</p>
      <p>${rd.ok ? 'Run it to see the fit for each location, what drove it, and how much evidence was available.' : esc(rd.summary)}</p>${rd.ok ? `<button class="btn pri sm" id="gaudgo">${esc(rd.mode.actionLabel)}</button>` : ''}</div>` : '';
  if (res && res.recipe.id === v.recipe) {
    const r = G.current(), [bl, bc] = C.band(r.score.value), ranked = G.ranked();
    detail = `<div class="gx-grid2"><div class="gx-card"><h4>Audience fit <small>deterministic</small></h4><div class="gx-big">${r.score.value ?? 'n/a'}<small><span class="gx-pill ${bc}">${bl}</span> · evidence coverage ${Math.round(r.score.coverage * 100)}%</small></div>
        <h5>Why this score</h5>${r.score.contributions.map(c => `<div class="gx-bar2"><span>${esc(c.label)} <small>weight ${c.weight}</small></span><div><i style="width:${c.normalized == null ? 0 : Math.round(c.normalized * 100)}%;background:${M.color(res, c.cat)}"></i></div><b>${c.points == null ? '–' : c.points}</b></div>`).join('')}<p class="gx-fine">Points show each factor's contribution to the score. A dash means no evidence, which is left out, not counted as zero.</p></div>
      <div class="gx-card"><h4>Supporting factors</h4>${r.score.contributions.map(c => `<div class="gx-li"><span><i style="background:${M.color(res, c.cat)}"></i>${esc(c.label)}</span><b>${c.count == null ? 'Unknown' : (c.capped ? '≥ ' : '') + c.count}</b><small>${C.km(r.features[c.cat] && r.features[c.cat].nearestM)}</small></div>`).join('')}${r.official ? `<div class="gx-li"><span>Official area context</span><b>${num(r.official.population)}</b><small>${esc(r.official.year)}</small></div>` : ''}</div></div>
      ${ranked.length > 1 ? `<div class="gx-card" style="margin-top:14px"><h4>Relevant OOH <small>ranked for ${esc(res.recipe.label)}</small></h4><table class="gx-t"><thead><tr><th>#</th><th>Site</th><th>Fit</th><th>Coverage</th></tr></thead><tbody>${ranked.map((x, i) => `<tr data-pick="${esc(x.site.id)}"><td>${i + 1}</td><td dir="auto">${esc(x.site.name || x.site.id)}</td><td><b>${x.score.value ?? 'n/a'}</b></td><td>${Math.round(x.score.coverage * 100)}%</td></tr>`).join('')}</tbody></table></div>` : ''}
      <details class="gx-card" style="margin-top:14px"><summary>Advanced controls · factor weights</summary><p class="gx-fine">Planning assumptions. Change a weight and re-score; nothing else changes.</p><div class="gx-weights">${res.recipe.factors.map(f => `<label>${esc(meta.categories[f.cat])}<input type="number" min="0.5" max="10" step="0.5" data-w="${f.cat}" value="${f.w}"></label>`).join('')}</div><button class="btn sm" id="gapw">Re-score with these weights</button>${tunedBlock(G)}</details>`;
  }
  el.innerHTML = `<div class="gx-auds" role="group" aria-label="Audience">${cards}</div>${detail}`;
  { const b = $('#gaudgo'); if (b) b.onclick = () => $('#gprimary').click(); }
  $$('[data-ra]').forEach(b => b.onclick = () => { v.recipe = b.dataset.ra; v.recipeSet = true; const ga = $('#gaud'); if (ga) ga.value = v.recipe; v.weights = null; PI.geoBrief.readyUI(G); if (v.result && v.sites) G.analyse(v.sites, { stay: true, selection: v.result.selection, preflight: v.result.preflight }); else T.audience(el, G); });
  $$('[data-pick]').forEach(tr => tr.onclick = () => { G.select(tr.dataset.pick); v.tab = 'map'; G.show(); });
  const ap = $('#gapw'); if (ap) ap.onclick = () => { v.weights = Object.fromEntries($$('[data-w]').map(i => [i.dataset.w, +i.value])); G.logBrain({ t: 'weights', recipe: v.recipe, weights: v.weights }); G.analyse(v.sites, { stay: true }); };
  const tb = $('#gtuned'); if (tb) tb.onclick = () => { v.weights = JSON.parse(tb.dataset.w); G.analyse(v.sites, { stay: true }); };
};

/* ===== 4. Competitors & POIs: networks first (no OOH or objective needed), then what surrounds one analysed place ===== */
const COV = { 'complete-as-observed': ['Everything Google returned', 'ok'], partial: ['Partial: locations may be missing', 'warn'], 'first-party': ['Your own list', 'ok'], 'not searched': ['Not searched', 'mut'], failed: ['Search failed', 'bad'] };
const NETCOL = ['#E5486F', '#7A5AF8', '#D99A12', '#17A2B8', '#F07C3C'];
function networkView(G) {
  const { v, C } = G, n = v.net, a = n.analysis, client = n.networks.find(x => x.role === 'client'), rivals = n.networks.filter(x => x.role === 'rival'), col = x => x.role === 'client' ? '#12121A' : NETCOL[rivals.indexOf(x) % NETCOL.length];
  const P = { DO: 'ok', TE: 'warn', WA: 'mut' };
  return `<div class="gx-hero"><div><small>Competitor landscape${n.industry ? ' · ' + esc(n.industry) : ''}${n.inv ? ' · OOH from ' + esc(n.inv) : ' · no OOH inventory in this run'} · circles of ${C.km(a.radius)}</small><h3>${n.networks.map(x => esc(x.name)).join(' <span class="gx-fine">vs</span> ')}</h3></div>
      <div class="gx-netcards">${n.networks.map(x => { const [cl, cc] = COV[x.coverage.status] || COV.failed, [pl] = PI.geoBrief.PROV[x.provenance] || ['']; return `<div class="gx-netc"><b><i style="background:${col(x)}"></i>${esc(x.name)}</b><span class="gx-pill ${x.role === 'client' ? 'ok' : ''}">${x.role === 'client' ? 'Your network' : 'Rival'}</span><div class="gx-big">${x.branches.length}<small>branch${x.branches.length === 1 ? '' : 'es'} found</small></div>
        <span class="gx-pill ${cc}">${cl}</span><p class="gx-fine">${x.coverage.status === 'first-party' ? 'From your own list.' : `${x.counts.returned} returned · ${x.counts.matched} matched the name · ${x.counts.excluded} excluded · ${x.counts.duplicates} duplicates · ${x.counts.unresolved} unresolved${x.counts.atms ? ' · ' + x.counts.atms + ' ATMs kept apart as context' : ''}${x.counts.offices ? ' · ' + x.counts.offices + ' offices kept apart' : ''}. ${x.coverage.areasSearched} of ${x.coverage.areasTotal} Qatar areas searched${x.coverage.cached ? ', answered from the database' : ''}.`}${pl ? ' ' + esc(pl) + '.' : ''} <span title="${esc(x.coverage.note)}">${esc(x.coverage.note)}</span></p></div>`; }).join('')}</div>
      <div class="gx-acts"><button class="btn pri sm" id="gnsave">${I('save')}Save</button><button class="btn sm" id="gncsv">${I('download')}Export findings (CSV)</button>${a.oohAdjacency.length ? `<button class="btn sm" id="gncmp">${I('layers')}Send the nearest OOH to Site Comparison</button>` : ''}<small>Change the circle size under Fine-tune and press Discover again: stored searches cost nothing.</small></div></div>
    ${n.expired ? `<div class="notice info">${I('info')}<div>This snapshot is older than 30 days, so Google's coordinates were removed as Google requires. The numbers below are as saved. Refresh to map the branches again.</div></div>` : ''}
    <div class="gx-top"><div class="gx-map card"><div class="gx-mapbox" id="gmapbox"></div><div class="gx-ctl"><button class="btn xs" id="gnfit">${I('target')}Fit networks</button><button class="btn xs" id="gqatar">Qatar</button></div>
        <div class="gx-layers"><b>On the map</b>${n.networks.map(x => `<label><i style="background:${col(x)}"></i> ${esc(x.name)} (${x.branches.filter(b => b.lat != null).length})</label>`).join('')}${a.gaps.length ? '<label><i style="background:#D99A12;border-radius:2px"></i> Coverage gap (hypothesis)</label>' : ''}${a.oohAdjacency.length ? '<label><i style="background:#2F6BFF"></i> OOH near rivals</label>' : ''}<small>Dots are where Google returned a location. A missing dot is not proof of no branch.</small></div></div>
      <div class="gx-card"><h4>What to do <small>rule-based</small></h4><ul class="gx-list">${a.actions.map(x => `<li><span class="gx-pill ${P[x.priority.slice(0, 2)]}">${x.priority}</span> ${esc(x.action)}<small>${esc(x.reason)} <b>Check first:</b> ${esc(x.validate)}${x.ids.length ? ' · ' + x.ids.map(esc).join(', ') : ''}</small></li>`).join('') || '<li>Add your own network to see gaps and overlap.</li>'}</ul>
        <p class="gx-fine">No opportunity score is shown here: this view describes where the networks are. Set an objective in the brief and use Opportunity Analysis to rank sites.</p></div></div>
    <div class="gx-row2"><div class="gx-card"><h4>Presence by municipality <small>locations found</small></h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>Municipality</th>${client ? `<th>${esc(client.name)}</th>` : ''}${rivals.map(x => `<th>${esc(x.name)}</th>`).join('')}<th>Population (2020 census)</th></tr></thead><tbody>${a.byMunicipality.map(m => `<tr><td>${esc(m.municipality)}</td>${client ? `<td><b>${m.client}</b></td>` : ''}${rivals.map(x => `<td>${m.rivals[x.name] || 0}</td>`).join('')}<td>${m.population ? num(m.population) : '<span class="gx-fine">Unknown</span>'}</td></tr>`).join('') || '<tr><td colspan="9">No location could be placed in a municipality.</td></tr>'}</tbody></table></div><p class="gx-fine">Population is for the whole municipality and is context only.</p></div>
      <div class="gx-card"><h4>Overlap with your network <small>${C.km(a.radius)} circles, counted once</small></h4>${client ? `<div class="gx-tw"><table class="gx-t"><thead><tr><th>Rival</th><th>Your branches with this rival nearby</th><th>Shared area</th><th>Share of your area</th></tr></thead><tbody>${a.overlap.map(o => `<tr><td>${esc(o.rival)}</td><td>${o.clientBranchesWithRivalNearby} of ${o.clientBranches}</td><td>${o.sharedKm2} km²</td><td>${o.shareOfClientArea == null ? '–' : o.shareOfClientArea + '%'}</td></tr>`).join('')}</tbody></table></div>` : '<p class="gx-fine">Name your own network in the brief, or choose a client location list, to see overlap and gaps.</p>'}</div></div>
    ${client ? `<div class="gx-row2"><div class="gx-card"><h4>Nearest rival to each of your branches</h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>Your branch</th><th>Nearest rival</th><th>Distance</th><th>Rivals within ${C.km(a.radius)}</th></tr></thead><tbody>${a.proximity.slice().sort((x, y) => y.rivalsWithin - x.rivalsWithin).slice(0, 15).map(p => `<tr><td dir="auto">${esc(short(p.name || p.id))}<small>${esc(p.municipality || '')}</small></td><td>${p.nearestRival ? esc(p.nearestRival.brand) : '–'}</td><td>${p.nearestRival ? C.km(p.nearestRival.distanceM) : '–'}</td><td><b>${p.rivalsWithin}</b>${p.brandsWithin.length ? '<small>' + p.brandsWithin.map(esc).join(', ') + '</small>' : ''}</td></tr>`).join('')}</tbody></table></div>${a.proximity.length > 15 ? `<p class="gx-fine">The 15 most contested of ${a.proximity.length} branches.</p>` : ''}</div>
      <div class="gx-card"><h4>Coverage gaps <small>hypotheses, not proof of demand</small></h4>${a.gaps.length ? `<div class="gx-tw"><table class="gx-t"><thead><tr><th>Gap</th><th>Rivals there</th><th>Your nearest branch</th><th>OOH nearby</th></tr></thead><tbody>${a.gaps.map(g => `<tr><td><b>${g.id}</b> ${esc(g.municipality || '')}<small>${g.lat}, ${g.lon}</small></td><td>${g.rivalBranches}<small>${g.brands.map(esc).join(', ')}</small></td><td>${C.km(g.nearestClientM)}</td><td>${g.oohNearby}${g.oohIds.length ? '<small>' + g.oohIds.slice(0, 3).map(esc).join(', ') + '</small>' : ''}</td></tr>`).join('')}</tbody></table></div>` : '<p class="gx-fine">No place was found where rivals are present and your network is more than ' + C.km(2 * a.radius) + ' away.</p>'}<p class="gx-fine">A gap means rivals were found where you have no branch nearby. It does not show unmet demand, and a partial search can hide your own or their locations.</p></div></div>` : ''}
    ${a.oohAdjacency.length ? `<div class="gx-card" style="margin-bottom:14px"><h4>OOH near rival locations <small>${a.oohAdjacency.length} assets within ${C.km(a.radius)}</small></h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>Asset</th><th>Supplier and format</th><th>Rival locations nearby</th><th>Your nearest branch</th></tr></thead><tbody>${a.oohAdjacency.slice(0, 15).map(x => `<tr><td><button class="gx-link" data-near="${esc(x.id)}"><b dir="auto">${esc(short(x.name || x.id))}</b></button><small>${esc(x.id)}</small></td><td>${[x.vendor, x.format].filter(Boolean).map(esc).join(' · ')}</td><td>${x.rivalsWithin}<small>${x.brands.map(esc).join(', ')}</small></td><td>${C.km(x.nearestClientM)}</td></tr>`).join('')}</tbody></table></div><p class="gx-fine">Nearness is context for conquesting. It does not show that a screen faces the branch, who passes it, or that it is available.</p></div>` : ''}
    <div class="gx-row2"><details class="gx-card"><summary><b>Branch roster</b> · ${n.networks.reduce((s, x) => s + x.branches.length, 0)} locations</summary><div class="gx-tw"><table class="gx-t"><thead><tr><th>Business</th><th>Location</th><th>Municipality</th><th>Source</th><th>Reference</th></tr></thead><tbody>${n.networks.flatMap(x => x.branches.map(b => `<tr><td><i class="gx-dot" style="background:${col(x)}"></i>${esc(x.name)}</td><td dir="auto">${esc(short(b.name || x.name))}</td><td>${esc(b.municipality || 'Unknown')}</td><td>${{ google_observed: 'Google Places', first_party: 'Your list', first_party_confirmed: 'Your list, also on Google', google_observed_not_in_list: 'Google only, not in your list' }[b.source] || esc(b.source)}</td><td><small>${esc(String(b.placeId || b.id).slice(0, 18))}</small></td></tr>`)).join('')}</tbody></table></div></details>
      <div class="gx-card"><h4>Evidence and limits</h4><ul class="gx-list">${n.evidence.map(e => `<li><b>${esc(e.id)} · ${esc(e.kind)}</b> ${esc(e.text)}<small>${esc([e.source, e.retrieved, e.cached ? 'stored result' : ''].filter(Boolean).join(' · '))}</small></li>`).join('')}</ul><ul class="gx-lim">${n.limits.map(l => `<li>${esc(l)}</li>`).join('')}</ul><p class="gx-fine">This run: ${n.quota.requests} new Google lookups, ${n.quota.cacheHits} businesses answered from the database. Method ${esc(n.analysisVersion)}, brand list ${esc(n.taxonomyVersion)}.</p></div></div>`;
}
T.comp = (el, G) => {
  const { v, C, M } = G, ST = window.PIGeoState, s = v.comp, picked = ST.chosenBrands(s), own = (v.bf.client || '').trim(), can = picked.length || own || v.clientLoc;
  const setup = v.netBusy ? `<div class="gx-empty"><span class="spin"></span><b>Looking for the networks</b><span>Each business is searched across six areas of Qatar, then matched, de-duplicated and compared.</span></div>`
    : v.netAsk ? `<div class="gx-card" role="alertdialog" aria-label="Confirm the search"><h4>Search Google for these businesses?</h4><p>${esc(v.netAsk.message)}</p><p class="gx-fine">A search returns what Google lists under each name: it is not an official register, and a busy area can return only part of a network. The result will say which.</p><div class="gx-acts"><button class="btn pri sm" id="gnyes">${I('search')}Search now</button><button class="btn sm" id="gnno">Cancel</button></div></div>`
    : v.netErr ? `<div class="notice err">${I('circle-alert')}<div>${esc(v.netErr)}</div></div>` : '';
  const guide = v.net || v.netBusy || v.netAsk ? '' : `<div class="gx-card"><h4>Explore competitors <small>no OOH inventory or objective needed</small></h4>
      <p>${s.industryId ? `Industry: <b>${esc(s.industryLabel)}</b>. ` : ''}${own ? `Your network: <b>${esc(own)}</b>. ` : ''}${picked.length ? `Rivals to look for: <b>${picked.map(b => esc(b.name)).join(', ')}</b>.` : s.none ? 'Competitors are switched off (None) in the brief.' : 'No rival is selected yet.'}</p>
      ${can ? `<button class="btn pri" data-act="discover">${I('search')}Discover and compare</button>` : `<p class="gx-fine">In the brief above, type the client or pick an industry. Suggested competitor types and rival names appear straight away, at no cost. Tick the rivals you want, or add your own.</p><button class="btn" data-focus="#gbc">Go to the brief</button>`}
      <p class="gx-fine">You will get: each network's locations with how complete the search was, a map of you and your rivals, presence by municipality, the nearest rival to each branch, overlap, coverage gaps as hypotheses, OOH near rival locations when an inventory is loaded, and next actions.</p></div>`;
  el.innerHTML = setup + guide + (v.net && !v.netBusy ? networkView(G) : '') + `<div id="gsitecomp" style="margin-top:14px"></div>`;
  $$('[data-act]').forEach(b => b.onclick = () => G.act(b.dataset.act)); $$('[data-focus]').forEach(b => b.onclick = () => { const f = $(b.dataset.focus); if (f) { f.scrollIntoView({ block: 'center' }); f.focus(); } });
  const y = $('#gnyes'); if (y) { y.onclick = () => G.discover(true); $('#gnno').onclick = () => { v.netAsk = null; T.comp(el, G); }; y.focus(); }
  if (v.net && !v.netBusy) {
    const n = v.net, a = n.analysis, rivals = n.networks.filter(x => x.role === 'rival'), col = x => x.role === 'client' ? '#12121A' : NETCOL[rivals.indexOf(x) % NETCOL.length];
    const paint = fit => { const box = $('#gmapbox'); if (!box) return; G.mapReady(box, ok => { if (ok) M.network({ networks: n.networks.map(x => ({ name: x.name, role: x.role, color: col(x), points: x.branches.filter(b => b.lat != null) })), gaps: a.gaps, radius: a.radius, ooh: a.oohAdjacency, fit, onPick: G.pickAsset }); else box.innerHTML = `<div class="gx-schem">${esc(v.mapNote || 'The map is unavailable. The tables below are complete.')}</div>`; }); };
    paint(true); $('#gnfit').onclick = () => paint(true); $('#gqatar').onclick = () => M.fitQatar();
    $('#gnsave').onclick = () => G.save('network');
    $$('[data-near]').forEach(b => b.onclick = () => G.pickAsset(b.dataset.near));
    const cmp = $('#gncmp'); if (cmp) cmp.onclick = () => { const all = G.oohAll(), sites = a.oohAdjacency.slice(0, 10).map(x => all.find(y => y.id === x.id)).filter(Boolean).map(x => ({ id: x.id, name: x.name, lat: x.lat, lon: x.lon, vendor: x.vendor, format: x.format })); v.afterRun = 'compare'; G.run({ sites, selection: { eligible: a.oohAdjacency.length, prescreened: a.oohAdjacency.length, enriched: sites.length, notEnriched: a.oohAdjacency.length - sites.length, excluded: {}, rule: `The ${sites.length} assets with the most rival brands nearby were taken from ${a.oohAdjacency.length} assets near rival locations.`, caveat: '', scope: null, inventory: a.oohAdjacency.length } }); };
    // Client-safe export: our own findings and first-party asset codes. Google's business names and coordinates are not exported.
    $('#gncsv').onclick = () => C.download(`competitors-${n.networks.map(x => x.name).join('-vs-').replace(/[^a-z0-9]+/gi, '-').toLowerCase()}.csv`, C.csv([['Section', 'Item', 'Value', 'Detail'],
      ...n.networks.map(x => ['Network', x.name, x.branches.length + ' branches found', `${x.role}; coverage: ${x.coverage.status}; ${x.coverage.note}`]),
      ...a.byMunicipality.flatMap(m => [...(n.networks.some(x => x.role === 'client') ? [['Presence', m.municipality, m.client, 'your network']] : []), ...Object.entries(m.rivals).map(([k, c]) => ['Presence', m.municipality, c, k])]),
      ...a.overlap.map(o => ['Overlap', o.rival, o.shareOfClientArea == null ? '' : o.shareOfClientArea + '% of your area', `${o.clientBranchesWithRivalNearby} of ${o.clientBranches} branches have this rival within ${a.radius} m`]),
      ...a.gaps.map(g => ['Coverage gap (hypothesis)', g.id + ' ' + (g.municipality || ''), g.rivalBranches + ' rival locations', `${g.brands.join(', ')}; OOH nearby: ${g.oohIds.join(', ') || 'none'}`]),
      ...a.oohAdjacency.map(x => ['OOH near rivals', x.id, x.rivalsWithin + ' rival locations', `${x.vendor} ${x.format}; ${x.brands.join(', ')}`]),
      ...a.actions.map(x => ['Action: ' + x.priority, x.action, x.reason, 'Check first: ' + x.validate]), ...n.limits.map(l => ['Limit', l, '', '']), ['Method', n.analysisVersion, n.taxonomyVersion, n.generatedAt]]));
  }
  const sc = $('#gsitecomp');
  if (v.result) siteComp(sc, G); else sc.innerHTML = `<div class="gx-card"><h4>Around one place <small>categories and named businesses</small></h4><p class="gx-fine">To count the businesses around a single place or OOH site, and list the nearest ones by name, choose "Understand a place or area" above, find the place and run it. This section then fills in.</p><button class="btn sm" data-mode-go="area">Understand a place</button></div>`;
  $$('[data-mode-go]').forEach(b => b.onclick = () => { const m = document.querySelector(`[data-mode="${b.dataset.modeGo}"]`); if (m) m.click(); const q = $('#gq'); if (q) { q.scrollIntoView({ block: 'center' }); q.focus(); } });
};
function siteComp(el, G) {
  const { v, C, M, meta } = G;
  const res = v.result, r = G.current(), cats = [...new Set([...res.recipe.factors.map(f => f.cat), ...(res.competitor ? [res.competitor] : [])])], pick = v.compCat || res.competitor || cats[0];
  const estKey = [r.site.id, pick, r.radius || res.radius].join('|'), est = (v.estCache || (v.estCache = {}))[estKey] || null;
  el.innerHTML = `<div class="gx-cats">${cats.map(c => { const f = r.features[c]; return `<button class="gx-catc ${c === pick ? 'on' : ''}" data-cc="${c}"><i style="background:${M.color(res, c)}"></i><b>${f ? (f.capped ? '≥ ' : '') + f.count : 'Unknown'}</b><small>${esc(meta.categories[c])}</small><span>${f && f.nearestM != null ? 'nearest ' + C.km(f.nearestM) : f && f.exact ? 'exact count' : ''}</span></button>`; }).join('')}</div>
    <div class="gx-card"><h4>${esc(meta.categories[pick])} near ${esc(r.site.name || r.site.id)} <small>${C.km(res.radius)} · ${r.features[pick] ? r.features[pick].count : '?'} counted</small></h4>
      <p class="gx-fine">Counts come from Places Aggregate. Load the establishments to see names, ratings and opening status for the nearest 20. This calls Google once and is not stored.</p>
      <button class="btn sm" id="gest" ${v.st.google && !est ? '' : 'disabled'}>${I('search')}${est ? 'Loaded (this session)' : 'Load establishments'}</button>${v.st.google ? '' : '<span class="gx-fine"> Google Maps is not configured.</span>'}
      ${est ? (est.error ? `<p class="gx-fine">${esc(est.error)}</p>` : `<div class="gx-tw"><table class="gx-t"><thead><tr><th>Business</th><th>Distance</th><th>Address</th><th></th></tr></thead><tbody>${est.list.map(e => `<tr><td dir="auto">${esc(e.name || 'Unnamed')}</td><td>${C.km(e.distanceM)}${e.distanceM <= res.radius ? '' : ' <small>outside</small>'}</td><td dir="auto"><small>${esc(e.address || '')}</small></td><td><button class="btn xs" data-det="${esc(e.id)}">Details</button> <button class="btn xs" data-enr="${esc(e.id)}" title="${v.st.enterpriseFields ? 'Fetches rating and opening hours for this one place' : 'Switched off to keep Google usage free'}">Rating &amp; hours</button></td></tr>`).join('')}</tbody></table></div><p class="gx-fine">Search order is not market share. Names are shown live. Ratings and opening hours cost more with Google, so they are fetched only for the one place you ask about${v.st.enterpriseFields ? '' : ' and are currently switched off'}.</p>`) : ''}</div>
    <div class="gx-card" style="margin-top:14px"><h4>Competitor pressure <small>transparent factors</small></h4>${r.pressure ? `<div class="gx-bar2"><span>Density (${r.pressure.count} within ${res.radius} m, saturates at 20)</span><div><i style="width:${Math.min(100, r.pressure.count * 5)}%"></i></div><b>${Math.min(100, r.pressure.count * 5)}</b></div>${r.pressure.nearestM != null ? `<div class="gx-bar2"><span>Proximity (nearest ${C.km(r.pressure.nearestM)})</span><div><i style="width:${Math.round(100 * (1 - Math.min(r.pressure.nearestM, res.radius) / res.radius))}%"></i></div><b>${Math.round(100 * (1 - Math.min(r.pressure.nearestM, res.radius) / res.radius))}</b></div>` : '<p class="gx-fine">Proximity needs the nearest-distance lookup, which loads with the map.</p>'}` : '<p class="gx-fine">Pick a competitor category above to measure pressure.</p>'}</div>`;
  $$('[data-cc]').forEach(b => b.onclick = () => { v.compCat = b.dataset.cc; siteComp(el, G); });
  const eb = $('#gest'); if (eb) eb.onclick = async () => { eb.disabled = true; eb.innerHTML = '<span class="spin"></span>'; try { const d = await PI.api('POST', 'geo/competitors', { lat: r.site.lat, lon: r.site.lon, radius: res.radius, type: pick }); v.estCache[estKey] = { list: d.establishments.sort((a, b) => a.distanceM - b.distanceM) }; } catch (e) { v.estCache[estKey] = { error: e.message }; } siteComp(el, G); };
  $$('[data-enr]').forEach(b => b.onclick = async () => { b.disabled = true; try { const dc = v.enrCache || (v.enrCache = {}); const d = dc[b.dataset.enr] || (dc[b.dataset.enr] = await PI.api('POST', 'geo/enrich', { id: b.dataset.enr })); PI.modal(`<h2>${esc(d.name || 'Place')}</h2><p>${d.rating != null ? '<b>' + d.rating + '</b> from ' + num(d.ratingCount || 0) + ' ratings' : 'No rating published'}${d.openNow == null ? '' : ' · ' + (d.openNow ? 'Open now' : 'Closed now')}</p>${d.hours ? `<ul class="gx-list">${d.hours.map(h => `<li>${esc(h)}</li>`).join('')}</ul>` : ''}<p class="gx-fine">A rating alone is not a performance score.</p>`); } catch (e) { PI.toast(e.message); } b.disabled = false; });
  $$('[data-det]').forEach(b => b.onclick = async () => { b.disabled = true; try { const dc = v.detCache || (v.detCache = {}); const d = dc[b.dataset.det] || (dc[b.dataset.det] = await PI.api('POST', 'geo/place', { id: b.dataset.det })); PI.modal(`<h2>${esc(d.name || 'Place')}</h2><p>${esc(d.address || '')}</p><p class="gx-fine">Rating and opening hours are separate (Rating &amp; hours).</p>`); } catch (e) { PI.toast(e.message); } b.disabled = false; });
};

/* ===== 5. Site Comparison ===== */
T.compare = (el, G) => {
  const { v, C, M } = G;
  const res = v.result, rows = res ? G.ranked() : []; if (rows.length < 2) { const n = v.inv && v.inv !== G.FOUND ? G.filtered().length : 0; el.innerHTML = `<div class="gx-empty">${I('layers')}<b>Comparison needs two or more analysed sites</b><span>${n >= 2 ? `The current list has ${n.toLocaleString('en-US')} assets. The best ${Math.min(10, n)} can be analysed and put side by side: they are ranked locally first and the rule is shown before anything runs.` : 'Choose an OOH inventory, or filter to the sites you want, then compare them here.'}</span>${n >= 2 ? `<button class="btn pri sm" id="gcmpgo">${I('layers')}Compare the best ${Math.min(10, n)}</button>` : '<button class="btn sm" data-focus="#ginv">Choose an inventory</button>'}</div>`; const b = $('#gcmpgo'); if (b) b.onclick = () => G.compareTop(); wireFocus(); return; }
  const sel = rows.filter(x => v.cmp.includes(x.site.id)).slice(0, 10);
  const metrics = [['Audience fit', x => x.score.value], ['Zone population', x => x.official ? x.official.population : null], ['Commercial context', x => x.contexts ? x.contexts.commercial.value : null], ['Premium context', x => x.contexts ? x.contexts.premium.value : null], ['Competitors nearby', x => x.pressure ? x.pressure.count : null], ['People in catchment (estimate)', x => x.populationEstimate ? x.populationEstimate.estimate : null], ['Drive time', x => v.routes[x.site.id] ? v.routes[x.site.id].seconds : null], ['Opportunity', x => C.opportunity(x, v.objective, v.routes[x.site.id], opx(G, x)).value], ['Evidence coverage', x => Math.round(x.score.coverage * 100)]];
  const fmt = (k, val) => val == null ? '<span class="gx-fine">Unknown</span>' : k === 'Drive time' ? C.mins(val) : k === 'Evidence coverage' ? val + '%' : num(val, /Opportunity|Audience fit|context/.test(k) ? 1 : 0);
  el.innerHTML = `<div class="gx-card"><h4>Choose 2 to 10 sites <small>${sel.length} selected</small></h4><div class="gx-chips">${rows.map(x => `<label class="${v.cmp.includes(x.site.id) ? 'on' : ''}"><input type="checkbox" data-cs="${esc(x.site.id)}" ${v.cmp.includes(x.site.id) ? 'checked' : ''}>${esc(short(x.site.name || x.site.id))}</label>`).join('')}</div></div>
    ${sel.length < 2 ? '<p class="gx-fine">Select at least two sites.</p>' : `<div class="gx-sumcards">${sel.map(x => { const o = C.opportunity(x, v.objective, v.routes[x.site.id], opx(G, x)), [bl, bc] = C.band(x.score.value); return `<div class="gx-card"><h4 dir="auto">${esc(short(x.site.name || x.site.id))}</h4><div class="gx-big">${o.value ?? 'n/a'}<small>Opportunity · <span class="gx-pill ${bc}">${bl}</span></small></div></div>`; }).join('')}</div>
    <div class="gx-card"><h4>Side by side <small>${esc(C.objLabel(v.objective))}</small></h4><div class="gx-tw"><table class="gx-t"><thead><tr><th>Metric</th>${sel.map(x => `<th dir="auto">${esc(short(x.site.name || x.site.id))}</th>`).join('')}</tr></thead><tbody>${metrics.map(([k, f]) => `<tr><td>${k}</td>${sel.map(x => `<td>${fmt(k, f(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="gx-fine">Unknown is not zero: a blank means no evidence. Official population is for the whole zone.</p></div>
    <div class="gx-grid2"><div class="gx-card"><h4>Factor comparison</h4><div id="cmpfac"></div></div><div class="gx-card"><h4>Map</h4><div class="gx-mapbox short" id="gmapbox"></div></div></div>
    <div class="gx-card"><h4>Accessibility <small>optional · uses the Routes API</small></h4><p class="gx-fine">Drive time is measured only for the 5 sites closest to the origin you give. It is not a drive-time catchment.</p>
      <div class="gx-inline"><input id="orig" placeholder="Origin coordinates, e.g. 25.2854, 51.5310" value="${esc(v.orig || '')}"><button class="btn sm" id="groute" ${v.st.google ? '' : 'disabled'}>${I('target')}Check drive time</button></div></div>`}`;
  $$('[data-cs]').forEach(c => c.onchange = () => { const s = new Set(v.cmp); c.checked ? s.add(c.dataset.cs) : s.delete(c.dataset.cs); if (s.size > 10) { s.delete(c.dataset.cs); PI.toast('Compare up to 10 sites'); } v.cmp = [...s]; T.compare(el, G); });
  if (sel.length < 2) return;
  const cats = res.recipe.factors.map(f => f.cat);
  PI.chart($('#cmpfac'), { type: 'bar', x: cats.map(c => G.meta.categories[c]), series: sel.slice(0, 6).map(x => ({ name: short(x.site.name || x.site.id), values: cats.map(c => (x.features[c] && x.features[c].count) || 0) })) });
  const box = $('#gmapbox'); G.mapReady(box, ok => { if (ok) { M.update({ res, r: G.current(), sites: sel, places: [], layers: { sites: true, rings: false, places: false, off: {} }, fit: 'all', onSelect: G.select }); (async () => { try { v.muniGeo = v.muniGeo || await PI.api('GET', 'geo/boundaries/municipalities'); } catch (_) { return; } if (M.map) M.setMask(v.muniGeo, v.layers.lock !== false); })(); } else box.innerHTML = M.schematic({ ...res, results: sel }, sel[0], { layers: { sites: true, rings: false, places: false, off: {} }, placesFor: () => [] }, true, true); });
  const rb = $('#groute'); if (rb) rb.onclick = async () => {
    const m = /^\s*(-?\d{1,3}(?:\.\d+)?)\s*[, ]\s*(-?\d{1,3}(?:\.\d+)?)\s*$/.exec($('#orig').value); if (!m) return PI.toast('Enter origin coordinates as latitude, longitude'); v.orig = $('#orig').value;
    const from = { lat: +m[1], lon: +m[2] }, ok0 = v.routeOrigin === `${from.lat},${from.lon}`; if (!ok0) { v.routes = {}; v.routeOrigin = `${from.lat},${from.lon}`; }
    const close = sel.slice().sort((a, b) => ((a.site.lat - from.lat) ** 2 + (a.site.lon - from.lon) ** 2) - ((b.site.lat - from.lat) ** 2 + (b.site.lon - from.lon) ** 2)).slice(0, 5).filter(x => !v.routes[x.site.id]);
    if (!close.length) return PI.toast('Those drive times are already measured. Nothing new to request.');
    rb.disabled = true; rb.innerHTML = '<span class="spin"></span>';
    try { const d = await PI.api('POST', 'geo/route', { from, to: close.map(x => ({ id: x.site.id, lat: x.site.lat, lon: x.site.lon })) }); d.routes.forEach(x => { if (!x.error) v.routes[x.id] = x; }); const bad = d.routes.filter(x => x.error).length; if (bad) PI.toast(bad + ' route(s) could not be measured'); } catch (e) { PI.toast(e.message); }
    T.compare(el, G);
  };
};

/* ===== 6. Opportunity Analysis: the brief's objective ranks the analysed sites; without an objective nothing is ranked ===== */
function briefLine(G) { const { v, C, meta } = G; return `<div class="gx-card gx-bline"><div><b>Brief</b> ${[v.bf.client && esc(v.bf.client), v.bf.product && esc(v.bf.product), 'Objective: <b>' + esc(C.objLabel(v.objective)) + '</b>', 'Audience: <b>' + esc((meta.recipes.find(r => r.id === v.recipe) || {}).label || '') + '</b>', v.bf.period && 'from ' + esc(v.bf.period), v.comp.none ? 'Competitors: none' : v.competitor && 'Competitors counted: ' + esc(meta.categories[v.competitor] || v.competitor)].filter(Boolean).join(' · ')}</div><button class="btn xs" data-focus="#gbo">Edit the brief</button></div>`; }
const wireFocus = () => $$('[data-focus]').forEach(b => b.onclick = () => { const f = $(b.dataset.focus); if (f) { f.scrollIntoView({ block: 'center' }); f.focus(); } });
T.opp = (el, G) => {
  const { v, C } = G, rec = C.OBJECTIVES[v.objective], rd = PI.geoBrief.ready(G);
  if (!rec) { el.innerHTML = briefLine(G) + `<div class="gx-empty small">${I('target')}<b>No objective is set, so nothing is ranked</b><span>Without an objective this workspace only describes places. Choose the campaign objective in the brief and the analysed sites are ranked for it${v.suggestObj ? `, or use the suggested one for this industry: <b>${esc(C.objLabel(v.suggestObj))}</b>` : ''}.</span><button class="btn sm" data-focus="#gbo">Choose an objective</button></div>`; return wireFocus(); }
  if (!v.result) { el.innerHTML = briefLine(G) + `<div class="gx-empty small">${I('map-pin')}<b>${rd.ok ? 'Ready to rank' : 'One more thing before ranking'}</b><span>${rd.ok ? 'The sites are scored on places around them, official area context and competitors, weighted for ' + esc(rec.label.toLowerCase()) + '. You will get a ranked list, why each site ranks where it does, and what to do next.' : esc(rd.summary)}</span>${rd.ok ? `<button class="btn pri sm" id="gopgo">${I('sparkles')}${esc(rd.mode.actionLabel)}</button>` : ''}${v.plan ? '<button class="btn sm" data-tab-go="plan">Open the plan</button>' : ''}</div>`; const g = $('#gopgo'); if (g) g.onclick = () => $('#gprimary').click(); $$('[data-tab-go]').forEach(b => b.onclick = () => { v.tab = b.dataset.tabGo; G.show(); }); return wireFocus(); }
  const res = v.result, list = G.ranked().map(r => ({ r, o: C.opportunity(r, v.objective, v.routes[r.site.id], opx(G, r)) })).sort((a, b) => (b.o.value ?? -1) - (a.o.value ?? -1) || String(a.r.site.id).localeCompare(String(b.r.site.id))), w = rec.w, ok = list.filter(x => x.o.status === 'ok'), acts = list.map(x => ({ ...x, a: C.actionFor(x.o) }));
  const grp = k => acts.filter(x => x.a.priority === k);
  el.innerHTML = briefLine(G) + coverageNote(res) + `<div class="gx-card" style="margin-top:14px"><h4>Ranked for ${esc(rec.label.toLowerCase())} <small>${esc(res.recipe.label)} · ${ok.length} of ${list.length} sites have enough evidence · recipe ${esc(C.RECIPE_VERSION)}</small></h4>
      <p class="gx-fine">Weights: audience fit ${w.audience} · official context ${w.official} · ${rec.competition === 'presence' ? 'competitor presence (more is better here)' : 'competitor gap (fewer is better)'} ${w.competition} · client coverage ${w.coverage} · accessibility ${w.access}. The index compares these sites with each other under this objective. It is not footfall, reach or a forecast.</p>
      <div class="gx-tw"><table class="gx-t"><thead><tr><th>#</th><th>Site</th><th>Index</th><th>Range</th><th>What moved it</th><th>Evidence</th><th>Do</th></tr></thead><tbody>${acts.map(({ r, o, a }, i) => `<tr data-pick="${esc(r.site.id)}"><td>${o.value == null ? '–' : i + 1}</td><td dir="auto"><b>${esc(short(r.site.name || r.site.id))}</b><small>${esc(r.site.id)}</small></td><td><b>${o.value ?? 'Not enough evidence'}</b></td><td>${o.low == null ? '–' : o.low + ' to ' + o.high}</td><td>${o.parts.map(p => `<span class="gx-chip2 ${p.value == null ? 'na' : ''}" title="${esc(p.why + '. ' + p.note)}">${esc(p.label)} ${p.value == null ? 'unknown' : Math.round(p.value * 100)}${p.points != null ? ' (+' + p.points + ')' : ''}</span>`).join('')}</td><td>${Math.round(o.coverage * 100)}%</td><td><span class="gx-pill ${a.cls}">${a.priority}</span></td></tr>`).join('')}</tbody></table></div>
      <p class="gx-fine">The range shows how far the index could move if the unknown parts were known. "Not enough evidence" means a number would mislead. Click a row to open the site.</p></div>
    <div class="gx-row2" style="margin-top:14px"><div class="gx-card"><h4>Action matrix</h4>${['DO NOW', 'TEST', 'WATCH'].map(k => `<h5><span class="gx-pill ${k === 'DO NOW' ? 'ok' : k === 'TEST' ? 'warn' : 'mut'}">${k}</span> ${grp(k).length}</h5><ul class="gx-list">${grp(k).slice(0, 5).map(x => `<li dir="auto"><b>${esc(x.r.site.name || x.r.site.id)}</b> <small>${esc(x.r.site.id)} · ${esc(x.a.reason)} ${esc(x.a.next)}</small></li>`).join('') || '<li><small>None.</small></li>'}${grp(k).length > 5 ? `<li><small>and ${grp(k).length - 5} more in the table</small></li>` : ''}</ul>`).join('')}</div>
      <div class="gx-card"><h4>Why the top sites rank where they do</h4>${ok.slice(0, 3).map(({ r, o }) => { const s = C.story(r, o, r.radius || res.radius), up = o.parts.filter(p => p.points != null).sort((a, b) => b.points - a.points)[0], dn = o.parts.filter(p => p.value != null).sort((a, b) => a.value - b.value)[0]; return `<h5 dir="auto">${esc(r.site.name || r.site.id)} · ${o.value}</h5><p class="gx-fine" style="margin-top:0">${esc(s.signal)}. ${esc(s.implication)} Strongest part: ${esc(up.label.toLowerCase())} (+${up.points}). Weakest: ${esc(dn.label.toLowerCase())} (${Math.round(dn.value * 100)} of 100).${o.missing.length ? ' Not measured: ' + esc(o.missing.join(', ').toLowerCase()) + '.' : ''}${o.seasonAdj ? ' Timing ' + pct(o.seasonAdj) + ' (assumption, not measured).' : ''}</p>`; }).join('') || '<p class="gx-fine">No site has enough evidence to rank. Connect Google Maps data or add official zones, then run again.</p>'}
        <p class="gx-fine">A different objective can reorder these sites: the same evidence is weighed differently. Change the objective in the brief to see it.</p></div></div>
    <div class="gx-card" style="margin-top:14px">${aiBlock(G)}<ul class="gx-lim">${res.limits.map(l => `<li>${esc(l)}</li>`).join('')}</ul></div>`;
  wireFocus(); wireAi(G); $$('[data-pick]').forEach(tr => tr.onclick = () => { G.select(tr.dataset.pick); v.tab = 'map'; G.show(); });
};

/* ===== 7. Saved Analyses ===== */
T.saved = async (el, G) => {
  el.innerHTML = '<div class="gx-empty"><span class="spin"></span></div>';
  let list = []; try { list = (await PI.api('GET', 'db/geosaved')).map(r => ({ id: r.id, ...r.data })).filter(d => !S.clientId || !d.client || d.client === S.clientId).sort((a, b) => b.savedAt - a.savedAt); } catch (_) { }
  const KIND = { plan: 'Plan', network: 'Competitor networks', analysis: 'Site analysis' };
  const what = d => { const k = d.kind || 'analysis', r = d.result || {}; return k === 'plan' ? `${(r.winner && r.winner.assets.length) || 0} assets chosen · ${esc((r.recipe || {}).label || '')}` : k === 'network' ? `${(r.networks || []).length} networks · ${(r.networks || []).reduce((s, n) => s + n.branches.length, 0)} locations` : `${esc((r.recipe || {}).label || '')} · ${r.radius} m · ${(r.results || []).length} site${(r.results || []).length === 1 ? '' : 's'}`; };
  el.innerHTML = brainCard(G) + `<div class="gx-card" style="margin-top:14px"><h4>Saved analyses <small>${list.length}</small></h4>${list.length ? list.map(d => { const age = Math.floor((Date.now() - d.savedAt) / 864e5); return `<div class="gx-li gx-sv" style="grid-template-columns:1fr auto auto auto"><span><b dir="auto">${esc(d.name)}</b><small style="display:block;text-align:left">${KIND[d.kind || 'analysis']} · ${what(d)} · saved ${PI.when(d.savedAt)}${d.brief && d.brief.objective ? ' · ' + esc(G.C.objLabel(d.brief.objective)) : ''}${age > 30 ? ' · older than 30 days' : ''}</small></span><button class="btn xs" data-open="${d.id}">Open</button><button class="btn xs" data-ref="${d.id}" title="Runs the saved question again and shows what changed">Refresh and compare</button><button class="btn xs" data-del="${d.id}" aria-label="Delete ${esc(d.name)}">${I('x')}</button></div>`; }).join('') : '<p class="gx-fine">Nothing is saved yet. Use Save on a plan, a competitor comparison or a site analysis.</p>'}
    <p class="gx-fine">Opening shows exactly what was saved and makes no Google request. Refresh is a separate step: it runs the question again and tells you what moved.</p></div>`;
  const rb = $('#gbreset'); if (rb) rb.onclick = async () => { if (!confirm('Forget everything the Geo brain has learned? Saved analyses are not affected.')) return; try { await PI.api('DELETE', 'db/geobrain/' + (S.clientId || '_team')); G.v.brain = G.BR.emptyBrain(); T.saved(el, G); } catch (e) { PI.toast(e.message); } };
  const by = id => list.find(d => d.id === id);
  $$('[data-open]').forEach(b => b.onclick = () => G.open(by(b.dataset.open)));
  $$('[data-ref]').forEach(b => b.onclick = () => { G.v.pendingRefresh = true; G.open(by(b.dataset.ref)); });
  $$('[data-del]').forEach(b => b.onclick = async () => { if (!confirm('Delete this saved analysis?')) return; try { await PI.api('DELETE', 'db/geosaved/' + b.dataset.del); T.saved(el, G); } catch (e) { PI.toast(e.message); } });
};
})();
